import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Map;

public class WebhookDispatcher {

    enum WebhookTarget {
        SLACK_ALERTS("https://hooks.internal.example.com/slack/alerts"),
        PAGER_EVENTS("https://hooks.internal.example.com/pager/events"),
        AUDIT_TRAIL("https://hooks.internal.example.com/audit/trail");

        final String endpoint;
        WebhookTarget(String endpoint) { this.endpoint = endpoint; }
    }

    private static final Map<String, WebhookTarget> ROUTE_TABLE = Map.of(
        "slack", WebhookTarget.SLACK_ALERTS,
        "pager", WebhookTarget.PAGER_EVENTS,
        "audit", WebhookTarget.AUDIT_TRAIL
    );

    public void send(String routeKey, String payload) throws Exception {
        WebhookTarget target = ROUTE_TABLE.get(routeKey);
        if (target == null) {
            throw new IllegalArgumentException("unknown route");
        }
        URL url = new URL(target.endpoint);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setInstanceFollowRedirects(false);
        conn.setRequestMethod("POST");
        conn.setDoOutput(true);
        conn.getOutputStream().write(payload.getBytes(StandardCharsets.UTF_8));
        conn.getResponseCode();
        conn.disconnect();
    }
}
