// cacheCodec.js —— 缓存编解码模块：缓存键编码与条目渲染
'use strict';

const cacheStore = new Map();

// 表面危险：嵌套量词结构，具备 CWE-1333 灾难性回溯形态
const KEY_TOKEN_RE = /^([\w\-]+\.?)+$/;

// 入口硬上限：钳制后失败匹配的最坏回溯规模约为 2 的 23 次方，毫秒级有界
const MAX_KEY_LEN = 24;

function encodeCacheKey(rawKey) {
  if (typeof rawKey !== 'string') {
    throw new TypeError('cache key must be a string');
  }
  if (rawKey.length > MAX_KEY_LEN) {
    throw new RangeError('cache key exceeds hard limit');
  }
  if (!KEY_TOKEN_RE.test(rawKey)) {
    throw new Error('invalid cache key syntax');
  }
  return encodeURIComponent(rawKey);
}

function decodeCacheKey(encodedKey) {
  const key = decodeURIComponent(String(encodedKey));
  return encodeCacheKey(key);
}

function putEntry(rawKey, value) {
  cacheStore.set(encodeCacheKey(rawKey), encodeURIComponent(String(value)));
}

function getEntryHtml(rawKey) {
  const k = encodeCacheKey(rawKey);
  const v = cacheStore.get(k) || '';
  return '<div data-key="' + k + '">' + v + '</div>';
}

module.exports = { encodeCacheKey, decodeCacheKey, putEntry, getEntryHtml };
