package main

import (
	"bytes"
	"encoding/gob"
	"fmt"
	"os/exec"
)

// OpsTask 为消息总线投递的运维任务载荷，经 gob 反序列化还原。
type OpsTask struct {
	Action string
	Raw    map[string]string
}

// allowActions 为精确白名单：穷举全部允许动作并映射到固定 argv。
var allowActions = map[string][]string{
	"disk_usage": {"/bin/df", "-h"},
	"mem_free":   {"/bin/free", "-m"},
	"svc_status": {"/bin/systemctl", "status", "crond"},
}

// RunTask 反序列化载荷并仅执行白名单内的运维命令。
func RunTask(payload []byte) (string, error) {
	var task OpsTask
	if err := gob.NewDecoder(bytes.NewReader(payload)).Decode(&task); err != nil {
		return "", fmt.Errorf("decode payload: %w", err)
	}
	argv, ok := allowActions[task.Action]
	if !ok {
		return "", fmt.Errorf("action rejected: %q", task.Action)
	}
	cmd := exec.Command(argv[0], argv[1:]...)
	out, err := cmd.CombinedOutput()
	return string(out), err
}

func main() {
	var buf bytes.Buffer
	_ = gob.NewEncoder(&buf).Encode(OpsTask{Action: "disk_usage", Raw: map[string]string{"path": "/tmp"}})
	out, err := RunTask(buf.Bytes())
	fmt.Println(out, err)
}
