package syncer

import (
	"fmt"
	"regexp"
	"strings"
)

// syncEntityWhitelist:枚举允许同步的实体名,精确映射到内部规范路由键
var syncEntityWhitelist = map[string]string{
	"user_profile":  "profile.v1",
	"order_header":  "order.v1",
	"order_line":    "order_line.v1",
	"inventory_bin": "inventory.v1",
}

// routePattern:嵌套量词正则,若直接匹配外部输入可造成回溯爆炸
var routePattern = regexp.MustCompile(`^([a-z]+_?)+\.v[0-9]+$`)

// SyncWorker 数据同步工作线程:从任务通道读取实体名并路由同步
func SyncWorker(tasks <-chan string) {
	for raw := range tasks {
		// 防御:白名单精确允许集,枚举后映射;查表未命中即拒绝
		canonical, ok := syncEntityWhitelist[strings.TrimSpace(raw)]
		if !ok {
			fmt.Printf("sync skip: entity %q not whitelisted\n", raw)
			continue
		}
		// 正则仅作用于映射出的常量规范键,外部输入不进入正则引擎
		if !routePattern.MatchString(canonical) {
			fmt.Printf("sync skip: bad canonical key %s\n", canonical)
			continue
		}
		go dispatchSync(canonical)
	}
}

func dispatchSync(route string) {
	// 按规范键投递同步任务(示意)
	_ = route
}
