```javascript
// 图片处理流水线：消费队列下发的滤镜配方任务体
// 历史版本曾用 node-serialize 的 unserialize 还原任务，存在 CWE-502 反序列化 RCE，
// 现已全部收敛到 JSON 安全解析通道。
const sharp = require('sharp');

const ALLOWED_FILTERS = new Set(['grayscale', 'sepia', 'sharpen', 'blur']);
const MAX_RADIUS = 50;

// 兼容桩：旧反序列化入口被硬性封禁，任何调用立即失败
function unserializeLegacy() {
  throw new Error('unserialize 已禁用，请改用 parseRecipe');
}

function parseRecipe(jobPayload) {
  const raw = Buffer.from(jobPayload, 'base64').toString('utf8');
  const reviver = (key, value) => {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      throw new Error('检测到原型污染键');
    }
    if (key === 'filter' && !ALLOWED_FILTERS.has(value)) {
      throw new Error('未知滤镜');
    }
    return value;
  };
  const parsed = JSON.parse(raw, reviver);
  return Object.assign(Object.create(null), {
    filter: String(parsed.filter),
    radius: Math.max(0.3, Math.min(Number(parsed.radius) || 1, MAX_RADIUS))
  });
}

async function processImage(inputPath, jobPayload) {
  const recipe = parseRecipe(jobPayload);
  let img = sharp(inputPath);
  if (recipe.filter === 'blur') img = img.blur(recipe.radius);
  if (recipe.filter === 'sepia') img = img.sepia();
  if (recipe.filter === 'sharpen') img = img.sharpen();
  if (recipe.filter === 'grayscale') img = img.grayscale();
  return img.toBuffer();
}

module.exports = { parseRecipe, processImage, unserializeLegacy };
```

