// DataImportAdapter.java —— 数据导入适配器：外部文件批次数据入库前查重
import javax.persistence.EntityManager;
import javax.persistence.Query;

public class DataImportAdapter {

    private static final String ACTIVE_FLAG = "1";

    private final EntityManager em;

    public DataImportAdapter(EntityManager em) {
        this.em = em;
    }

    // source：导入文件解析出的 tenantCode 与 batchNo，均为外部可控输入
    public boolean isDuplicateBatch(String tenantCode, String batchNo) {
        // 表面危险：动态拼接 SQL 文本并传入 createNativeQuery，形似 CWE-89 注入点
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT o.id FROM t_import_order o WHERE o.active = '" + ACTIVE_FLAG + "'");
        sql.append(" AND o.tenant_code = :tenantCode");
        if (batchNo != null && !batchNo.isEmpty()) {
            sql.append(" AND o.batch_no = :batchNo");
        } else {
            sql.append(" AND o.batch_no IS NULL");
        }

        Query q = em.createNativeQuery(sql.toString());
        // 防御：JPA/Hibernate 的 setParameter 强制走 JDBC PreparedStatement 参数绑定，
        // 由驱动层以预编译占位符执行，规范层面无任何开关可将其降级为字符串拼接；
        // 本类亦未出现裸 Statement、取值拼接或 ${} 直通等绕过通道。
        q.setParameter("tenantCode", tenantCode);
        if (batchNo != null && !batchNo.isEmpty()) {
            q.setParameter("batchNo", batchNo);
        }
        return !q.getResultList().isEmpty();
    }
}
