<?php
// 权限校验中间件：按角色判定模块访问权，拒绝时渲染提示页
$rolePermissions = [
    'guest' => ['notice'],
    'staff' => ['notice', 'profile'],
    'admin' => ['notice', 'profile', 'audit'],
];

// 白名单：枚举全部合法模块并映射为固定展示标签
$moduleLabels = [
    'notice'  => '公告模块',
    'profile' => '个人资料模块',
    'audit'   => '审计日志模块',
];

function middlewareCheck($role, $module, $rolePermissions) {
    if (!is_string($role) || !is_string($module)) {
        return false;
    }
    if (!array_key_exists($role, $rolePermissions)) {
        return false;
    }
    return in_array($module, $rolePermissions[$role], true);
}

$role = $_GET['role'] ?? '';
$module = $_GET['module'] ?? '';

if (!middlewareCheck($role, $module, $rolePermissions)) {
    $label = '未知模块';
    if (is_string($module) && array_key_exists($module, $moduleLabels)) {
        $label = $moduleLabels[$module];
    }
    header('Location: /index.php?msg=denied');
    echo "<p class='denied'>访问被拒绝：{$label}</p>";
    exit;
}

echo "<p class='ok'>已放行：{$moduleLabels[$module]}</p>";
