// 邮件模板服务：根据模板 ID 渲染邮件 HTML
const express = require('express');
const { exec } = require('child_process');
const { promisify } = require('util');
// db 为 SQLite 封装；email_templates 表仅由运维部署脚本写入，业务侧无写入口
const db = require('./db');
const execAsync = promisify(exec);
const app = express();

// GET /render?templateId=welcome&locale=zh-CN
app.get('/render', async (req, res) => {
  const { templateId, locale } = req.query;

  // 预编译语句：templateId 与 locale 仅作为绑定参数，绝不拼接进 SQL 文本
  const row = db.prepare(
    'SELECT file_path, engine FROM email_templates WHERE template_id = ? AND locale = ?'
  ).get(templateId, locale);

  if (!row) {
    return res.status(404).json({ error: 'template not found' });
  }

  // 命令中的变量均取自服务端登记的模板表字段，请求输入不参与命令构造
  const { stdout } = await execAsync(`${row.engine} render ${row.file_path}`);
  res.type('html').send(stdout);
});

app.listen(8080);
```

