<?php
declare(strict_types=1);

// 静态资源服务：按用户请求返回静态文件并探测其 MIME 类型
$resourceDir = '/var/www/static';

$file = $_GET['file'] ?? '';
if ($file === '' || str_contains($file, chr(0))) {
    http_response_code(400);
    exit('bad request');
}

$baseReal = realpath($resourceDir);
$targetReal = realpath($resourceDir . '/' . $file);

// 真实路径必须落在资源根目录内，拒绝目录穿越与符号链接逃逸
if ($baseReal === false || $targetReal === false
    || !str_starts_with($targetReal, $baseReal . DIRECTORY_SEPARATOR)) {
    http_response_code(403);
    exit('forbidden');
}

// 关键防御：escapeshellarg 将整个路径编码为单一 shell 字面量参数，
// 分号、管道、反引号、命令替换等元字符全部退化为普通字符，无法逃逸
$quoted = escapeshellarg($targetReal);
$raw = shell_exec('file -b --mime-type ' . $quoted);

$mime = trim((string) $raw);
// 纵深防御：MIME 必须是纯 token，杜绝 CRLF 注入响应头
if (!preg_match('/^[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*\/[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*$/', $mime)) {
    http_response_code(500);
    exit('mime detect failed');
}

header('Content-Type: ' . $mime);
readfile($targetReal);
