import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;

/** 搜索索引构建器：为文档生成索引用指纹 */
public class SearchIndexBuilder {

    // 白名单：索引指纹仅允许以下强摘要算法，枚举精确映射 JCE 名称
    private enum FingerprintAlgo {
        SHA256("SHA-256"),
        SHA512("SHA-512");

        private final String jceName;

        FingerprintAlgo(String jceName) {
            this.jceName = jceName;
        }

        static FingerprintAlgo fromTaskConfig(String raw) {
            for (FingerprintAlgo a : values()) {
                if (a.name().equalsIgnoreCase(raw)) {
                    return a;
                }
            }
            throw new IllegalArgumentException("unsupported algo: " + raw);
        }
    }

    // rawAlgo 来自索引任务配置（外部输入），历史版本曾默认 MD5
    public String buildFingerprint(String docId, String rawAlgo) throws Exception {
        FingerprintAlgo algo = FingerprintAlgo.fromTaskConfig(rawAlgo);
        MessageDigest md = MessageDigest.getInstance(algo.jceName());
        byte[] digest = md.digest(docId.getBytes(StandardCharsets.UTF_8));
        return HexFormat.of().formatHex(digest);
    }
}
