package ops.exec;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

/** 运维命令封装库：磁盘用量只读诊断命令执行器 */
public class DiskUsageCommand {

    /** 固定白名单二进制，命令名不来自任何外部输入 */
    private static final String DF_BIN = "/usr/bin/df";

    /**
     * 查询指定挂载点的磁盘用量；userPath 来自工单系统，属不可信输入。
     */
    public String queryDiskUsage(String userPath) throws Exception {
        if (userPath == null || userPath.isEmpty()) {
            throw new IllegalArgumentException("mount point required");
        }
        // 防御核心：命令与参数按 argv 分离传递，不拼接 shell 命令串，
        // 全程不启动 /bin/sh，分号、竖线、反引号、命令替换等元字符不会被二次解释
        List<String> argv = new ArrayList<>();
        argv.add(DF_BIN);        // 槽位0：固定命令
        argv.add("-h");          // 槽位1：固定选项
        argv.add("--");          // 槽位2：终止选项解析，防连字符开头输入被当作选项
        argv.add(userPath);      // 槽位3：不可信输入仅占独立参数槽位

        ProcessBuilder pb = new ProcessBuilder(argv);
        pb.redirectErrorStream(true);
        Process proc = pb.start();

        byte[] out = proc.getInputStream().readAllBytes();
        if (!proc.waitFor(10, TimeUnit.SECONDS)) {
            proc.destroyForcibly();
            throw new IllegalStateException("df timeout");
        }
        return new String(out, java.nio.charset.StandardCharsets.UTF_8);
    }
}
