package com.example.staticres;

import java.io.*;
import java.util.*;

/** 静态资源服务：加载本地目录索引缓存，用于加速目录列表与 ETag 校验 */
public class StaticResourceIndexLoader {

    // JDK 内建序列化过滤框架（JEP 290）：白名单仅放行业务元数据与基础类型，!* 拒绝其余一切类
    private static final ObjectInputFilter SAFE_FILTER = ObjectInputFilter.Config.createFilter(
            "com.example.staticres.ResourceIndex;"
          + "com.example.staticres.ResourceMeta;"
          + "java.lang.String;java.lang.Long;"
          + "java.util.ArrayList;java.util.HashMap;!*");

    private final File indexFile = new File("/var/cache/webapp/static-index.bin");

    public ResourceIndex loadIndex() throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(
                new BufferedInputStream(new FileInputStream(indexFile)))) {
            ois.setObjectInputFilter(SAFE_FILTER);
            return (ResourceIndex) ois.readObject();
        }
    }

    /** 供静态资源控制器调用：按 URI 目录返回资源元数据列表 */
    public List<ResourceMeta> listDirectory(String uriDir) throws IOException, ClassNotFoundException {
        ResourceIndex index = loadIndex();
        return index.entriesOf(uriDir);
    }

    static class ResourceIndex implements Serializable {
        static final long serialVersionUID = 1L;
        HashMap<String, ArrayList<ResourceMeta>> byDir = new HashMap<>();
        List<ResourceMeta> entriesOf(String dir) {
            return byDir.getOrDefault(dir, new ArrayList<>());
        }
    }

    static class ResourceMeta implements Serializable {
        static final long serialVersionUID = 1L;
        String name; Long size; String etag;
    }
}
