// 会话管理组件：根据 Cookie 中的会话 ID 从磁盘加载会话文件
const path = require('path');
const fs = require('fs').promises;

const SESSION_ROOT = path.resolve(__dirname, 'sessions');

// 来源：HTTP Cookie 头中解析出的会话 ID，属于不可信外部输入
function parseSessionId(cookieHeader) {
  const pair = String(cookieHeader || '')
    .split(';')
    .map(function (s) { return s.trim(); })
    .find(function (s) { return s.indexOf('sid=') === 0; });
  return pair ? pair.slice(4) : '';
}

async function loadSession(cookieHeader) {
  const sid = parseSessionId(cookieHeader);
  if (!/^[0-9a-f]{32}$/.test(sid)) {
    throw new Error('malformed session id');
  }
  const target = path.resolve(SESSION_ROOT, sid + '.json');
  const rel = path.relative(SESSION_ROOT, target);
  if (rel === '' || rel === '..' || rel.indexOf('..' + path.sep) === 0 || path.isAbsolute(rel)) {
    throw new Error('session path escapes session root');
  }
  const content = await fs.readFile(target, 'utf8');
  const session = JSON.parse(content);
  return JSON.stringify({
    sid: session.sid,
    user: session.user,
    expiresAt: session.expiresAt
  });
}

module.exports = { loadSession, SESSION_ROOT };
```

