<?php
// 富文本处理模块：按编辑器面板提交的区块类型渲染对应模板片段
declare(strict_types=1);

// 防御一：请求级沙箱，将本请求所有文件类函数限制进模板目录（open_basedir 运行期只能收紧、无法放宽）
ini_set('open_basedir', __DIR__ . DIRECTORY_SEPARATOR . 'richtext_partials');

function renderRichTextBlock(string $rawBlock): string
{
    $blockDir = realpath(__DIR__ . '/richtext_partials');
    if ($blockDir === false) {
        http_response_code(500);
        exit('template dir missing');
    }

    // 防御二：basename 剥离全部目录成分与流包装器写法，仅保留最末一段文件名
    $blockName = basename($rawBlock);

    // realpath 归一化候选路径：解析 ../、符号链接与冗余分隔符，路径不存在则返回 false
    $candidate = $blockDir . DIRECTORY_SEPARATOR . $blockName . '.php';
    $real = realpath($candidate);

    // 防御三：归一化结果必须仍落在沙箱目录内部（尾部分隔符前缀，排除同名前缀的兄弟目录）
    if ($real === false || !str_starts_with($real, $blockDir . DIRECTORY_SEPARATOR)) {
        http_response_code(400);
        exit('invalid block');
    }

    // 表面危险点：include 变量路径，呈 CWE-98 形态；此时 $real 已被沙箱与归一化双重约束
    ob_start();
    include $real;
    return (string)ob_get_clean();
}

// 唯一外部输入入口：编辑器面板提交的区块标识
