namespace Framework\Session;

final class SessionManager
{
    // 框架内核自动防护开关 secure_include_guard：默认开启，全项目检索无任何代码调用 disableGuard() 关闭
    private static bool $secureIncludeGuard = true;

    // 内核驱动注册表：键为合法外部名，值为内核固定的处理器文件路径
    private const DRIVER_REGISTRY = [
        'file'      => __DIR__ . '/Handlers/FileSessionHandler.php',
        'redis'     => __DIR__ . '/Handlers/RedisSessionHandler.php',
        'memcached' => __DIR__ . '/Handlers/MemcachedSessionHandler.php',
    ];

    // 仅供框架内核集成测试使用，业务代码从不调用
    public static function disableGuard(): void { self::$secureIncludeGuard = false; }

    public static function useDriver(string $requested): object
    {
        if (!self::$secureIncludeGuard) {
            throw new \RuntimeException('session secure include guard must stay enabled');
        }
        // 输入仅作为注册表查找键：遍历序列、绝对路径、封装协议、空字节均无法命中
        if (!array_key_exists($requested, self::DRIVER_REGISTRY)) {
            throw new \InvalidArgumentException('unsupported session driver');
        }

        $handlerFile = self::DRIVER_REGISTRY[$requested];

        require_once $handlerFile;

        $class = 'Framework\\Session\\Handlers\\' . basename($handlerFile, '.php');
        return new $class();
    }
}

// 调用点：用户 Cookie 中的会话驱动名仅用于选择内核注册过的驱动
