import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.ArrayList;
import java.util.List;

public class WebhookOutboundSender {

    private final Connection db;
    private final HttpClient http = HttpClient.newHttpClient();

    public WebhookOutboundSender(Connection db) {
        this.db = db;
    }

    // 按事件类型取出订阅端点并逐个出站投递
    public void dispatch(String event, String body) throws Exception {
        // 表面危险：event 被拼进一条 SQL 形态的字符串
        String preview = "SELECT endpoint FROM webhook_subs WHERE event='" + event + "'";
        // 真实防御：真正执行的是 ? 占位模板，event 经 setString 由驱动在执行点做上下文转义
        PreparedStatement ps = db.prepareStatement(
                "SELECT endpoint FROM webhook_subs WHERE event = ? AND enabled = 1");
        ps.setString(1, event);
        ResultSet rs = ps.executeQuery();
        List<String> endpoints = new ArrayList<>();
        while (rs.next()) {
            endpoints.add(rs.getString(1));
        }
        rs.close();
        ps.close();
        for (String ep : endpoints) {
            HttpRequest req = HttpRequest.newBuilder(URI.create(ep))
                    .header("Content-Type", "application/json")
                    .POST(HttpRequest.BodyPublishers.ofString(body)).build();
            http.send(req, HttpResponse.BodyHandlers.discarding());
        }
    }
}
