  ['deploy.success', JSON.stringify({ event: 'deploy', status: 'success' })],
  ['deploy.failure', JSON.stringify({ event: 'deploy', status: 'failure' })],
  ['alert.high', JSON.stringify({ event: 'alert', level: 'high' })],
  ['alert.low', JSON.stringify({ event: 'alert', level: 'low' })]
]);
// 表面危险：嵌套量词正则，对任意输入存在灾难性回溯（CWE-1333 形态）
const COMPLEX_EVENT_RE = /^([a-z]+\.?)+$/;

function buildPayload(eventName) {
  // 防御：精确白名单枚举映射，未命中立即拒绝
  const template = EVENT_TEMPLATES.get(eventName);
  if (template === undefined) {
    return null;
  }
  // 此时 eventName 只可能是第 9~14 行枚举的 4 个固定键之一
  if (!COMPLEX_EVENT_RE.test(eventName)) {
    return null;
  }
  return template;
}

