```go
package main

import (
	"io"
	"net/http"
	"regexp"
	"time"
)

// 路由正则含嵌套量词与交替，回溯型引擎下是典型 ReDoS 炸弹；
// 防御：Go regexp 基于 RE2 自动机，线性时间匹配，无灾难性回溯。
var routePattern = regexp.MustCompile(`^(?:/gw/)+[a-z0-9-]+/(?:v1|v2)+(?:/.*)*$`)

var upstreamClient = &http.Client{Timeout: 5 * time.Second}

func forward(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path
	// 第二道防御：匹配前对可控路径施加长度上限，压缩匹配成本上界。
	if len(path) > 2048 {
		http.Error(w, "path too long", http.StatusRequestURITooLong)
		return
	}
	if !routePattern.MatchString(path) {
		http.Error(w, "route not found", http.StatusNotFound)
		return
	}
	target := "http://127.0.0.1:9090" + path
	req, err := http.NewRequestWithContext(r.Context(), http.MethodGet, target, nil)
	if err != nil {
		http.Error(w, "bad upstream request", http.StatusBadRequest)
		return
	}
	resp, err := upstreamClient.Do(req)
	if err != nil {
		http.Error(w, "upstream unreachable", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	w.Header().Set("Content-Type", resp.Header.Get("Content-Type"))
	io.Copy(w, resp.Body)
}
func main() {
	http.HandleFunc("/gw/", forward)
	_ = http.ListenAndServe(":8080", nil)
}
