package com.example.session;

import java.io.IOException;
import java.util.concurrent.TimeUnit;

/** 会话管理组件：吊销会话并写审计日志、清理会话锁文件 */
public class SessionRevocationService {

    // 输出上下文编码器：把任意输入编码为 POSIX shell 单引号字面量参数
    private static String shellQuote(String raw) {
        StringBuilder sb = new StringBuilder(raw.length() + 2);
        sb.append('\'');
        for (int i = 0; i < raw.length(); i++) {
            if (raw.charAt(i) == '\'') {
                sb.append("'\\''");
            } else {
                sb.append(raw.charAt(i));
            }
        }
        sb.append('\'');
        return sb.toString();
    }

    // sessionId 来自请求 Cookie，是攻击者可控的外部输入
    public void revoke(String sessionId) throws IOException, InterruptedException {
        String cmd = "logger -t session-audit revoke " + shellQuote(sessionId)
                + "; rm -f " + shellQuote("/var/run/sessions/" + sessionId + ".lock");
        ProcessBuilder pb = new ProcessBuilder("/bin/sh", "-c", cmd);
        pb.redirectErrorStream(true);
        Process proc = pb.start();
        if (!proc.waitFor(5, TimeUnit.SECONDS)) {
            proc.destroyForcibly();
        }
    }
}
