<?php
// 模板渲染辅助：把模板里的 {{remote_asset url="..."}} 占位符替换为远端样式片段
function renderTemplate(string $tpl): string {
    return preg_replace_callback(
        '/\{\{remote_asset\s+url="([^"]+)"\}\}/',
        function (array $m): string { return fetchAsset($m[1]); },
        $tpl
    );
}

function fetchAsset(string $url): string {
    $parts = parse_url($url);                       // 原生安全解析，失败返回 false
    if ($parts === false || !isset($parts['scheme'], $parts['host'])) {
        return '<!-- invalid asset url -->';
    }
    if (!in_array($parts['scheme'], ['http', 'https'], true)) {
        return '<!-- scheme not allowed -->';
    }
    $ip = gethostbyname($parts['host']);            // 先解析成最终 IP 再校验
    if ($ip === $parts['host']) {
        return '<!-- dns resolve failed -->';
    }
    // 原生过滤器：拒绝私网段与保留段(127.0.0.0/8、10/8、172.16/12、192.168/16、169.254/16、0/8 等)
    if (!filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE)) {
        return '<!-- blocked host -->';
    }
    $port = $parts['port'] ?? ($parts['scheme'] === 'https' ? 443 : 80);
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT        => 5,
        CURLOPT_FOLLOWLOCATION => false,   // 关闭跟随重定向，防止跳转绕过校验
        CURLOPT_RESOLVE        => [$parts['host'] . ':' . $port . ':' . $ip], // 连接钉在已校验 IP，防 DNS rebinding
    ]);
    $body = curl_exec($ch);
    curl_close($ch);
    return is_string($body) ? $body : '<!-- fetch failed -->';
}

$tpl = '<div>{{remote_asset url="https://assets.example.com/widget.css"}}</div>';
