package com.ops.net;

import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.util.Set;

/** 运维命令封装库：向已登记的运维目标下发 TCP 探活命令 */
public final class OpsProbeCommand {

    // OpsFramework 启动时自动装载连接守卫，并从受控配置中心加载出口 IP 允许清单
    private static final Set<InetAddress> APPROVED_EGRESS = OpsRegistry.approvedEgressIps();

    static {
        // 运行时确认框架自动防护未被关闭：守卫未激活或允许清单为空即拒绝初始化
        if (!OpsRegistry.isConnectGuardActive() || APPROVED_EGRESS.isEmpty()) {
            throw new IllegalStateException("framework connect guard must stay enabled");
        }
    }

    /** @param targetHost 目标主机名，来自运维控制台输入（外部可控） */
    public String execute(String targetHost, int port) throws Exception {
        String host = targetHost.trim();
        // 守卫第一步：全量 DNS 解析，覆盖多记录与 IPv6，禁止按主机名直接建连
        InetAddress[] resolved = InetAddress.getAllByName(host);
        for (InetAddress ip : resolved) {
            // 守卫第二步：解析结果必须整体命中允许清单，任一未登记 IP 即拒绝
            if (!APPROVED_EGRESS.contains(ip)) {
                throw new SecurityException("target not registered in ops registry");
            }
        }
