const { exec } = require('child_process');
const { quote } = require('shell-quote');

const MAX_TERM_LEN = 64;

function buildSearchIndex(rawTerm, onDone) {
  // rawTerm 为前端搜索框传入的原始用户输入
  const term = String(rawTerm == null ? '' : rawTerm).slice(0, MAX_TERM_LEN);
  if (!term) {
    return onDone(new Error('empty search term'));
  }

  // 防御:在进入 shell 命令字符串之前,使用 shell-quote 的 quote()
  // 将整段输入编码为 POSIX 单引号字面量,使元字符失去语法含义
  const encodedTerm = quote([term]);

  const cmd = 'indexer --rebuild --term ' + encodedTerm;

  exec(cmd, { timeout: 5000, cwd: '/var/lib/search-index' }, (err, stdout, stderr) => {
    if (err) {
      return onDone(err);
    }
    onDone(null, { term: term, docCount: parseInt(stdout, 10) || 0 });
  });
}

module.exports = { buildSearchIndex };
