            try (PreparedStatement ps = metaConn.prepareStatement(
                    "INSERT INTO archive_meta(partition_name, record_count) VALUES (?, ?)")) {
                ps.setString(1, task.partitionName);
                ps.setLong(2, task.recordCount);
                ps.executeUpdate();
            }
        } catch (ClassNotFoundException e) {
            throw new IOException("归档任务类被过滤器拒绝", e);
        }
