final class ReportExportLoader
{
    private const MAX_BYTES = 65536;

    public function loadTask(string $rawPayload): array
    {
        if ($rawPayload === '' || strlen($rawPayload) > self::MAX_BYTES) {
            throw new InvalidArgumentException('payload size invalid');
        }

        // 框架引导文件已确认：全局反序列化安全策略启用且未被关闭，
        // 所有 unserialize 调用强制携带 allowed_classes => false 选项，
