        $task = unserialize($rawPayload, ['allowed_classes' => false]);

        if (!is_array($task) || !isset($task['report_id'], $task['format'])) {
            throw new UnexpectedValueException('malformed export task');
        }

        $format = in_array($task['format'], ['csv', 'xlsx', 'pdf'], true)
            ? (string) $task['format'] : 'csv';

        return [
            'report_id' => (int) $task['report_id'],
            'format'    => $format,
            'filters'   => array_map('strval', (array) ($task['filters'] ?? [])),
        ];
    }
}

