import java.io.IOException;
import java.io.OutputStream;
import java.net.URLEncoder;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;

public class SearchIndexBuilder {

    private static final Path INDEX_ROOT = Paths.get("/var/lib/search-index/shards");

    /** 外部请求传入查询词决定分片文件名，payload 为待索引内容字节。 */
    public Path writeShard(String rawTerm, byte[] payload) throws IOException {
        if (rawTerm == null || rawTerm.trim().isEmpty()) {
            throw new IllegalArgumentException("term must not be empty");
        }
        String shardKey = rawTerm.trim();
        // 表面危险：shardKey 来自外部请求，看似可携带 ../ 的路径片段（CWE-22 形态）
        // 真实防御：进入文件路径上下文前先做百分号输出编码，分隔符全部转义
        String safeName = URLEncoder.encode(shardKey, "UTF-8") + ".idx";
        Path target = INDEX_ROOT.resolve(safeName);
        Files.createDirectories(INDEX_ROOT);
        try (OutputStream out = Files.newOutputStream(target, StandardOpenOption.CREATE_NEW)) {
            out.write(payload);
        }
        return target;
    }
}
