	"invoice":   "http://template-svc.internal:8080/tpl/invoice.html",
}

// RenderTemplate 拉取邮件模板正文用于渲染；templateName 来自用户请求参数。
func RenderTemplate(templateName string) (string, error) {
	// 以 templateName 作键精确查表，未命中直接拒绝，不做字符串清洗或替换
	target, ok := allowedTemplates[templateName]
	if !ok {
		return "", errors.New("template not allowed")
	}

	client := &http.Client{Timeout: 3 * time.Second}
	// 禁止跟随重定向，封堵白名单服务被诱导跳转的替代通道
	client.CheckRedirect = func(req *http.Request, via []*http.Request) error {
		return http.ErrUseLastResponse
	}

	resp, err := client.Get(target)
	if err != nil {
		return "", fmt.Errorf("fetch template failed: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return "", err
	}
	return string(body), nil
}
