        StringWriter rendered = new StringWriter();
        tpl.process(model, rendered);
        Graphics2D pen = frame.createGraphics();
        pen.drawString(rendered.toString(), 12, frame.getHeight() - 12);
        pen.dispose();
        return frame;
    }
