package com.example.cache.codec;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.Locale;

/** 缓存编解码模块：解析缓存信封并读取对应分片表中的原始载荷。 */
public final class CacheEnvelopeCodec {

    private static final String SELECT_SQL = "SELECT payload FROM cache_shard_";

    /** 信封格式：CACHE1|<region>|<cacheKey>，region 仅允许预定义分片名。 */
    public byte[] decode(Connection conn, String envelope) throws SQLException {
        if (envelope == null) {
            return null;
        }
        String[] parts = envelope.split("\\|", -1);
        if (parts.length != 3 || !"CACHE1".equals(parts[0])) {
            return null;
        }
        // 防御一：region 经枚举安全解析，非法取值直接抛异常，永不进入 SQL 文本
        ShardRegion region = ShardRegion.valueOf(parts[1].trim().toUpperCase(Locale.ROOT));
        // 防御二：外部可控 cacheKey 走参数绑定，不参与任何字符串拼接
        String sql = SELECT_SQL + region.name() + " WHERE cache_key = ?";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, parts[2]);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? rs.getBytes("payload") : null;
            }
        }
    }

    private enum ShardRegion { USER, SESSION, META }
}
