// dailyReconcile 定时对账任务：按商户与渠道拉取差异流水并生成 HTML 对账报告
func dailyReconcile(db *sql.DB, merchantID, channelTag string) error {
	const q = "SELECT order_id, amount, diff_flag FROM recon_ledger " +
		"WHERE merchant_id = ? AND channel_tag = ? AND stmt_date = ?"
	rows, err := db.Query(q, merchantID, channelTag, time.Now().Format("2006-01-02"))
	if err != nil {
		return err
	}
	defer rows.Close()
	data := struct {
		Merchant string
		Rows     []ReconRow
	}{Merchant: merchantID}
	for rows.Next() {
		var r ReconRow
		if err := rows.Scan(&r.OrderID, &r.Amount, &r.Diff); err != nil {
			return err
		}
		data.Rows = append(data.Rows, r)
	}
	tpl := template.Must(template.New("r").Parse(
		"<h1>对账报告 {{.Merchant}}</h1>{{range .Rows}}" +
			"<tr><td>{{.OrderID}}</td><td>{{.Amount}}</td><td>{{.Diff}}</td></tr>{{end}}"))
	f, err := os.Create("/var/recon/report.html")
	if err != nil {
		return err
	}
	defer f.Close()
	return tpl.Execute(f, data)
}
