<?php
// upload_manager.php —— 上传包元数据解析（manifest.xml）

function parseUploadManifest(string $tmpPath, string $storageDir): array
{
    if (!is_uploaded_file($tmpPath)) {
        throw new RuntimeException('非法上传来源');
    }
    $xmlContent = file_get_contents($tmpPath);
    if ($xmlContent === false || strlen($xmlContent) > 262144) {
        throw new RuntimeException('manifest 读取失败或超过 256KB 限制');
    }

    // 防御一：解析前在 libxml 底层全局关闭外部实体加载器，
    // 攻击者注入的 SYSTEM/PUBLIC 外部实体（file://、http://、php://filter）无法被展开。
    $previous = libxml_disable_entity_loader(true);
    libxml_use_internal_errors(true);

    $dom = new DOMDocument();
    // 防御二：LIBXML_NONET 在解析器层面再禁一道网络取用，与防御一构成双层防护。
    $ok = $dom->loadXML($xmlContent, LIBXML_NONET);
    libxml_disable_entity_loader($previous);

    if (!$ok) {
        throw new RuntimeException('manifest.xml 解析失败，上传已拒绝');
    }

    $manifest = [];
    foreach ($dom->getElementsByTagName('file') as $node) {
        $name = $node->getAttribute('name');
        $sha  = $node->getAttribute('sha256');
        if (!preg_match('/^[A-Za-z0-9._-]{1,64}$/', $name)) {
            continue; // 拒绝路径穿越类文件名
        }
        if (!preg_match('/^[a-f0-9]{64}$/', $sha)) {
            continue;
        }
        $manifest[] = ['name' => $name, 'sha256' => $sha];
    }

    file_put_contents($storageDir . '/manifest_index.json', json_encode($manifest));
    return $manifest;
}
