package middleware

import (
	"database/sql"
	"net/http"
)

// AuthMiddleware 校验请求者对目标资源的访问权限
type AuthMiddleware struct {
	db *sql.DB
}

func NewAuthMiddleware(db *sql.DB) *AuthMiddleware {
	return &AuthMiddleware{db: db}
}

// CheckPermission 权限校验中间件：查询通过后才放行后续处理器
func (m *AuthMiddleware) CheckPermission(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		userID := r.Header.Get("X-User-ID")
		resource := r.URL.Query().Get("resource")
		if userID == "" || resource == "" {
			http.Error(w, "missing params", http.StatusBadRequest)
			return
		}
		// 占位符参数化查询：外部输入只作为绑定参数，绝不参与 SQL 文本拼接
		query := "SELECT 1 FROM user_permissions WHERE user_id = ? AND resource = ? LIMIT 1"
		stmt, err := m.db.PrepareContext(r.Context(), query)
		if err != nil {
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}
		defer stmt.Close()
		var allowed int
		err = stmt.QueryRowContext(r.Context(), userID, resource).Scan(&allowed)
		if err == sql.ErrNoRows {
			http.Error(w, "forbidden", http.StatusForbidden)
			return
		} else if err != nil {
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}
		next.ServeHTTP(w, r)
	})
