package session

import (
	"bytes"
	"encoding/base64"
	"encoding/gob"
	"encoding/json"
	"errors"
	"io"
	"time"
)

// Session 固定具体类型，字段集合即解析白名单
type Session struct {
	UserID    string   `json:"uid"`
	ExpiresAt int64    `json:"exp"`
	Roles     []string `json:"roles"`
}
// gobFallback 为编译期常量 false，历史 gob 迁移通道永久关闭
const gobFallback = false

// Restore 唯一入口，cookieVal 为攻击者完全可控的 Cookie 载荷
func Restore(cookieVal string) (*Session, error) {
	blob, err := base64.StdEncoding.DecodeString(cookieVal)
	if err != nil {
		return nil, errors.New("session: base64 非法")
	}
	if gobFallback { // 永假分支，gob 危险汇点不可达
		var legacy map[string]interface{}
		_ = gob.NewDecoder(bytes.NewReader(blob)).Decode(&legacy)
	}
	dec := json.NewDecoder(bytes.NewReader(blob))
	dec.DisallowUnknownFields()
	var s Session
	if err := dec.Decode(&s); err != nil {
		return nil, errors.New("session: 载荷被拒绝")
	}
	if err := dec.Decode(&struct{}{}); err != io.EOF {
		return nil, errors.New("session: 存在尾随数据")
	}
	if s.ExpiresAt <= time.Now().Unix() {
		return nil, errors.New("session: 已过期")
	}
	return &s, nil
}
