package richtext

import (
	"bytes"
	"encoding/gob"
	"html/template"
	"io"
	"net/http"
)

// RichFragment 富文本评论片段，仅含字符串字段
type RichFragment struct {
	Body   string
	Author string
}

var fragTmpl = template.Must(template.New("frag").
	Parse("<div class=\"comment\">{{.Body}}</div><span class=\"author\">{{.Author}}</span>"))

// HandleFragment 接收 gob 编码的富文本片段并渲染为 HTML
func HandleFragment(w http.ResponseWriter, r *http.Request) {
	var buf bytes.Buffer
	if _, err := io.Copy(&buf, r.Body); err != nil {
		http.Error(w, "read body failed", http.StatusBadRequest)
		return
	}
	var frag RichFragment
	// 对不可信请求体执行 gob 反序列化
	if err := gob.NewDecoder(&buf).Decode(&frag); err != nil {
		http.Error(w, "decode failed", http.StatusBadRequest)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	// 输出经 html/template 上下文自动转义
	if err := fragTmpl.Execute(w, frag); err != nil {
		http.Error(w, "render failed", http.StatusInternalServerError)
	}
}
