// 权限校验中间件：反序列化会话令牌，校验角色并回显拒绝原因
const HTML_ENTITY = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

function htmlEncode(value) {
  // 输出上下文编码：逐字符查实体表做白名单映射，命中则转实体，其余字符原样保留
  return Array.from(String(value)).map(ch => HTML_ENTITY[ch] || ch).join('');
}

const ALLOWED_ROLES = ['admin', 'editor', 'viewer'];

function unserializeToken(b64) {
  // 表面危险：对不可信令牌先 Base64 解码再反序列化（CWE-502 模式）
  return JSON.parse(Buffer.from(b64, 'base64').toString('utf8'));
}

function authMiddleware(req, res, next) {
  let session;
  try {
    session = unserializeToken(req.headers['x-session-token'] || '');
  } catch (err) {
    res.status(400).type('html').send('<p>会话令牌格式非法</p>');
    return;
  }
  if (typeof session !== 'object' || session === null) {
    res.status(400).type('html').send('<p>会话载荷结构非法</p>');
    return;
  }
  const user = typeof session.user === 'string' ? session.user : '';
  const role = typeof session.role === 'string' ? session.role : '';
  if (ALLOWED_ROLES.indexOf(role) === -1) {
    // 唯一回显出口：所有插值先经 htmlEncode 做 HTML 正文上下文编码
    res.status(403).type('html').send(
      '<p>用户 ' + htmlEncode(user) + ' 的角色 ' + htmlEncode(role) + ' 无权访问该资源</p>'
    );
    return;
  }
  req.auth = { user: user, role: role };
  next();
}

module.exports = { authMiddleware, htmlEncode };
