// ops-admin.js —— 运维命令封装库:安全查看应用日志尾部
'use strict';
const { execFile } = require('child_process');
const path = require('path');
const fs = require('fs');

const LOG_ROOT = path.resolve('/var/log/myapp');

function tailOperationLog(userSuppliedName, cb) {
  // 防御点1:规范化,把 ../ 与多余分隔符折叠为绝对路径
  const resolved = path.resolve(LOG_ROOT, userSuppliedName);
  let rel = path.relative(LOG_ROOT, resolved);
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) {
    return cb(new Error('rejected: path escapes LOG_ROOT'));
  }
  // 防御点2:解析软链接后的真实路径,再做一次包含性校验
  fs.realpath(resolved, (err, real) => {
    if (err) return cb(err);
    rel = path.relative(LOG_ROOT, real);
    if (rel.startsWith('..') || path.isAbsolute(rel)) {
      return cb(new Error('rejected: symlink escapes LOG_ROOT'));
    }
    // 防御点3:execFile + argv 数组且 shell:false,路径作为独立参数传递
    execFile('tail', ['-n', '100', real], { shell: false }, (err2, stdout) => {
      cb(err2, stdout);
    });
  });
}

module.exports = { tailOperationLog };
