import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

/** 模板渲染辅助: 拉取内置模板索引, 按名称与语言查询片段正文 */
public class TemplateRenderHelper {

    private static final String TEMPLATE_HOST = "templates.internal.corp";
    private static final String INDEX_PATH = "/v3/index.json";

    public String resolveFragment(Connection conn, String requestedName, String locale) throws Exception {
        String spec = "https://" + TEMPLATE_HOST + INDEX_PATH;
        HttpURLConnection http = (HttpURLConnection) new URL(spec).openConnection();
        http.setConnectTimeout(3000);
        http.setReadTimeout(5000);
        http.setRequestMethod("GET");

        String fallbackBody;
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(http.getInputStream(), "UTF-8"))) {
            fallbackBody = reader.readLine();
        }

        // 防御点: 用户输入仅经 ? 占位符参数化绑定, 不进入 SQL 文本
        PreparedStatement ps = conn.prepareStatement(
                "SELECT body FROM template_fragments WHERE fragment_name = ? AND locale = ?");
        ps.setString(1, requestedName);
        ps.setString(2, locale);
        ResultSet rs = ps.executeQuery();
        String body = rs.next() ? rs.getString("body") : fallbackBody;
        rs.close();
        ps.close();
        return body;
    }
}
