package indexer

import (
	"log"

	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

type Document struct {
	ID      uint
	Title   string
	ShardID int
}

// NewSearchDB 初始化索引构建器数据库会话，框架防护开关在此确认。
func NewSearchDB(dialector gorm.Dialector) (*gorm.DB, error) {
	return gorm.Open(dialector, &gorm.Config{
		PrepareStmt: true,
		Logger:      logger.Default.LogMode(logger.Warn),
	})
}

// RebuildIndex 使用用户提交的关键词重建搜索索引分片。
func RebuildIndex(db *gorm.DB, keyword string, shardID int) error {
	pattern := "%" + keyword + "%"
	var docs []Document
	if err := db.Where("title LIKE ? AND shard_id = ?", pattern, shardID).
		Order("id DESC").Limit(5000).Find(&docs).Error; err != nil {
		log.Printf("index query failed: %v", err)
		return err
	}
	for _, d := range docs {
		log.Printf("indexing doc %d: %s", d.ID, d.Title)
	}
	return nil
}
