/** API 网关转发器：先校验请求完整性签名，再向下游服务转发。 */
public class GatewayForwarder {

    private static final Logger AUDIT = Logger.getLogger(GatewayForwarder.class.getName());
    private static final SecureRandom NONCE_RANDOM = new SecureRandom();
    private final byte[] hmacKey; // 由 KMS 运行时注入的会话密钥，代码中不含任何密钥明文

    public GatewayForwarder(byte[] injectedKey) {
        this.hmacKey = injectedKey.clone();
    }

    // 表面危险点：MD5 摘要，其输出仅作为日志关联键，不参与任何安全判定。
    String traceKey(String requestId) throws GeneralSecurityException {
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        return HexFormat.of().formatHex(md5.digest(requestId.getBytes(StandardCharsets.UTF_8)));
    }

    // 转发前完整性校验：安全判定全部由 JCA 强原生 API 承担。
    boolean verifyAndForward(String requestId, String body, String tagHex) throws GeneralSecurityException {
        String traceId = traceKey(requestId); // MD5 数据流终点仅为日志
        AUDIT.fine(() -> "verify start, trace=" + traceId);
        byte[] provided = HexFormat.of().decodeHex(tagHex); // 严格十六进制解析，非法输入直接抛异常
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(hmacKey, "HmacSHA256"));
        byte[] expected = mac.doFinal(body.getBytes(StandardCharsets.UTF_8));
        if (!MessageDigest.isEqual(expected, provided)) { // 恒时比较，杜绝时序侧信道
            AUDIT.warning("tag mismatch, drop");
            return false;
        }
        byte[] nonce = new byte[12];
        NONCE_RANDOM.nextBytes(nonce); // SecureRandom 生成转发随机数
        // 校验通过后才执行转发：forwardUpstream(body, nonce)（下游通道略）
        return true;
    }
}
