import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;

/** 富文本处理模块：将富文本正文导出为指定格式文件 */
public class RichTextExporter {

    /** 导出格式白名单：枚举精确映射，工具路径与参数均为编译期常量 */
    public enum ExportFormat {
        PDF ("pdf",  "/opt/richtext/tools/export_pdf"),
        HTML("html", "/opt/richtext/tools/export_html"),
        TXT ("txt",  "/opt/richtext/tools/export_txt");

        final String label;
        final String toolPath;

        ExportFormat(String label, String toolPath) { this.label = label; this.toolPath = toolPath; }

        /** 精确等值匹配：命中返回枚举，未命中返回 null，绝不回退到原始输入 */
        static ExportFormat fromLabel(String raw) {
            for (ExportFormat f : values()) {
                if (f.label.equals(raw)) return f;
            }
            return null;
        }
    }

    /** 导出入口：requestedFormat 来自前端表单，content 为富文本正文 */
    public boolean export(String requestedFormat, String content) throws IOException, InterruptedException {
        ExportFormat fmt = ExportFormat.fromLabel(requestedFormat);
        if (fmt == null) {
            throw new IllegalArgumentException("format must be pdf, html or txt");
        }
        // 命令行参数全部取自枚举常量；正文经 stdin 传入，不进入命令行
        ProcessBuilder pb = new ProcessBuilder(fmt.toolPath, "--to", fmt.label);
        pb.redirectErrorStream(true);
        Process proc = pb.start();
        try (OutputStream stdin = proc.getOutputStream()) {
            stdin.write(content.getBytes(StandardCharsets.UTF_8));
        }
        return proc.waitFor() == 0;
    }
}
