// searchIndexBuilder.js —— 站内搜索索引构建器
const libxmljs = require('libxmljs2');

// 高危解析配置：开启实体替换、允许网络与 DTD 加载（表面 CWE-611 风险）
const PARSE_OPTS = { noent: true, nonet: false, dtdload: true };

// 白名单精确允许集：枚举全部合法文档类型，并映射到编译期固定 XML 模板
const ALLOWED_DOC_TYPES = Object.freeze(['product', 'faq', 'news']);
const XML_TEMPLATES = Object.freeze({
  product: '<?xml version="1.0"?><doc><title>Product Manual</title><body>Static built-in product text.</body></doc>',
  faq: '<?xml version="1.0"?><doc><title>FAQ</title><body>Static built-in faq text.</body></doc>',
  news: '<?xml version="1.0"?><doc><title>News</title><body>Static built-in news text.</body></doc>'
});

function buildIndexEntry(docType) {
  // 防御点一：精确枚举比对，非白名单取值直接拒绝
  if (typeof docType !== 'string' || !ALLOWED_DOC_TYPES.includes(docType)) {
    throw new Error('docType rejected: not in allowlist');
  }
  // 防御点二：映射到固定常量模板，外部输入仅作键名，永不拼入 XML
  const xml = XML_TEMPLATES[docType];
  const doc = libxmljs.parseXml(xml, PARSE_OPTS); // 危险 sink，但实参为常量
  return {
    docType: docType,
    title: doc.get('//title').text(),
    body: doc.get('//body').text()
  };
}

function handleRequest(query) {
  // 唯一入口：query.docType 是唯一不可信来源
  return buildIndexEntry(query.docType);
}

module.exports = { handleRequest };
