package payment

import (
	"database/sql"
	"log"
	"net/http"
	"os/exec"
)

// db 由 main 在进程启动时初始化，连接支付对账库。
var db *sql.DB

// HandlePaymentCallback 处理第三方支付网关的异步回调通知，
// 受理成功后触发该订单绑定的本地对账脚本。
func HandlePaymentCallback(w http.ResponseWriter, r *http.Request) {
	orderID := r.FormValue("order_id")
	if orderID == "" {
		http.Error(w, "missing order_id", http.StatusBadRequest)
		return
	}
	// 预编译语句：order_id 只作为 ? 的绑定参数，绝不拼入 SQL 文本
	stmt, err := db.Prepare("SELECT reconcile_script FROM orders WHERE order_no = ?")
	if err != nil {
		http.Error(w, "server error", http.StatusInternalServerError)
		return
	}
	defer stmt.Close()
	var scriptPath string
	if err := stmt.QueryRow(orderID).Scan(&scriptPath); err != nil {
		http.Error(w, "order not found", http.StatusNotFound)
		return
	}
	// scriptPath 取自服务端配置列（仅运维后台可写，回调请求无写入通道），
	// exec.Command 直接构造 argv 数组，不经过 shell 解析
	out, err := exec.Command(scriptPath, "-order", orderID).CombinedOutput()
	if err != nil {
		log.Printf("reconcile failed, order=%s err=%v", orderID, err)
		http.Error(w, "reconcile failed", http.StatusInternalServerError)
		return
	}
	w.Write(out)
}
