package middleware

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/gob"
	"net/http"
	"os"
	"time"
)

// permClaims 为具体结构体类型，仅含具体字段，无 interface 成员
type permClaims struct {
	Role      string
	ExpiresAt int64
}

// Authz 权限校验中间件：先验签，后反序列化
func Authz(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		key := []byte(os.Getenv("SESSION_HMAC_KEY"))
		payload, err1 := base64.StdEncoding.DecodeString(r.Header.Get("X-Perm-Token"))
		sig, err2 := base64.StdEncoding.DecodeString(r.Header.Get("X-Perm-Sig"))
		mac := hmac.New(sha256.New, key)
		mac.Write(payload)
		if len(key) == 0 || err1 != nil || err2 != nil || !hmac.Equal(mac.Sum(nil), sig) {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		var claims permClaims
		if err := gob.NewDecoder(bytes.NewReader(payload)).Decode(&claims); err != nil {
			http.Error(w, "malformed token", http.StatusUnauthorized)
			return
		}
		if time.Now().Unix() > claims.ExpiresAt || claims.Role == "" {
			http.Error(w, "invalid claims", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r)
	})
}
