<?php
declare(strict_types=1);

/**
 * OpsToolbox —— 运维命令封装库：按相对名称读取服务器日志快照
 */
final class OpsToolbox
{
    private const LOG_ROOT = '/var/log/myapp';

    /** @param string $relative 运维面板传入的相对路径，如 nginx/access.log */
    public function readLog(string $relative): string
    {
        // 表面危险点：外部输入直接拼进文件读取路径
        $candidate = self::LOG_ROOT . DIRECTORY_SEPARATOR . $relative;

        // 防御一：realpath 安全解析，折叠 ../、./、重复分隔符并解析符号链接
        $real = realpath($candidate);
        if ($real === false) {
            throw new RuntimeException('log_not_found');
        }

        // 防御二：对规范化结果做目录包含校验，构成沙箱边界
        $root = realpath(self::LOG_ROOT);
        if ($root === false || !str_starts_with($real, $root . DIRECTORY_SEPARATOR)) {
            throw new RuntimeException('path_outside_log_root');
        }

        // 唯一文件读取 sink：实参已是规范化且通过边界校验的绝对路径
        return file_get_contents($real);
    }
}
