import org.springframework.context.annotation.Bean;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.firewall.StrictHttpFirewall;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

// API 网关静态构件转发器：按请求路径回源读取本地构件并转发给调用方
@RestController
@EnableWebSecurity
public class ArtifactForwardController {

    private static final Path DOC_ROOT =
            Paths.get("/var/gateway/artifacts").toAbsolutePath().normalize();

    // 框架级防护：Spring Security 5+ 严格防火墙，保持全部默认拦截项开启
    // 默认拒绝原始 URI 中的 ../、./、//、%2e、%2f、%25、反斜杠、分号等序列
    @Bean
    public StrictHttpFirewall httpFirewall() {
        return new StrictHttpFirewall();
    }

    @GetMapping("/forward/{*artifactPath}")
    public ResponseEntity<byte[]> forward(@PathVariable String artifactPath) throws IOException {
        // 规范化后做前缀包含校验，兜底拦截绝对路径注入与残余穿越
        Path target = DOC_ROOT.resolve(artifactPath).normalize();
        if (!target.startsWith(DOC_ROOT)) {
            return ResponseEntity.status(HttpStatus.FORBIDDEN).build();
        }
        byte[] body = Files.readAllBytes(target);
        return ResponseEntity.ok(body);
    }
}
