import urllib.parse
import urllib.request
from string import Template

TRUSTED_TEMPLATE_HOSTS = frozenset({"templates.corp.example"})


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


_OPENER = urllib.request.build_opener(_NoRedirect)


def fetch_template(template_url: str) -> str:
    parsed = urllib.parse.urlparse(template_url)
    if parsed.scheme != "https" or parsed.hostname not in TRUSTED_TEMPLATE_HOSTS:
        raise ValueError("template source outside approved https host")
    if parsed.port not in (None, 443) or parsed.username or parsed.password:
        raise ValueError("unexpected authority components in template url")
    request = urllib.request.Request(
        urllib.parse.urlunparse(parsed._replace(params="", query="", fragment="")),
        headers={"Accept": "text/plain"},
    )
    with _OPENER.open(request, timeout=5) as response:
        return response.read(65536).decode("utf-8")


def render_greeting(template_url: str, visitor: str) -> str:
    body = fetch_template(template_url)
    return Template(body).safe_substitute(visitor=visitor)
