    static class ReconRecord implements Serializable {
        private static final long serialVersionUID = 1L;
        String accountNo;
        long amountCents;
    }

    // 定时对账入口：由调度器每小时调用一次
    public void reconcileHourly(Path snapshotDir) {
        Path file = snapshotDir.resolve("recon-" + LocalTime.now().getHour() + ".bin");
        if (!Files.exists(file)) {
            return;
        }
        // JVM 原生反序列化白名单过滤器（JEP 290）：仅放行 ReconRecord 与 String，其余类一律拒绝
        ObjectInputFilter filter = ObjectInputFilter.Config.createFilter(
                "com.bank.recon.ReconciliationTask$ReconRecord;java.lang.String;!*");
        try (ObjectInputStream ois = new ObjectInputStream(Files.newInputStream(file))) {
            ois.setObjectInputFilter(filter);
            ReconRecord record = (ReconRecord) ois.readObject();
            System.out.println("对账账户: " + record.accountNo + " 金额分: " + record.amountCents);
        } catch (IOException | ClassNotFoundException e) {
            // 过滤器拒绝、类不匹配或流损坏：按脏数据告警，不中断调度
            System.err.println("对账快照被拒绝: " + e.getMessage());
        }
    }
