// search_index_builder.php —— 搜索索引构建器：按文档键重建倒排索引条目

function persistStats(PDO $pdo, string $docKey, array $tokens): bool
{
    // stats_blob 唯一写入点：仅序列化内部计数结构
    $counts = array_count_values($tokens);
    $blob = serialize(['terms' => $counts, 'built_at' => time()]);
    $stmt = $pdo->prepare('UPDATE documents SET stats_blob = :blob WHERE doc_key = :key');
    $stmt->bindValue(':blob', $blob, PDO::PARAM_STR);
    $stmt->bindValue(':key', $docKey, PDO::PARAM_STR);
    return $stmt->execute();
}

function rebuildIndexEntry(PDO $pdo, string $docId): bool
{
    // 表面危险：外部输入参与查询；实际经预编译语句绑定，参数不进入 SQL 词法结构
    $stmt = $pdo->prepare('SELECT doc_key, stats_blob FROM documents WHERE doc_key = :key');
    $stmt->bindValue(':key', $docId, PDO::PARAM_STR);
    $stmt->execute();
    $row = $stmt->fetch(PDO::FETCH_ASSOC);
    if ($row === false) {
        return false;
    }
    // 表面危险：反序列化库内数据；实际为内部生成结构且禁止类实例化
    $stats = unserialize($row['stats_blob'], ['allowed_classes' => false]);
    if (!is_array($stats)) {
        return false;
    }
    $pairs = [];
    foreach (($stats['terms'] ?? []) as $term => $freq) {
        $pairs[] = $term . ':' . (int) $freq;
    }
    $ins = $pdo->prepare('REPLACE INTO inverted_index (doc_key, terms) VALUES (:key, :terms)');
    $ins->bindValue(':key', $row['doc_key'], PDO::PARAM_STR);
    $ins->bindValue(':terms', implode(',', $pairs), PDO::PARAM_STR);
    return $ins->execute();
}

