function load_cache_codec(PDO $pdo, string $cacheKey): string
{
    if ($cacheKey === '' || strlen($cacheKey) > 64) {
        throw new InvalidArgumentException('invalid cache key');
    }
    // 预编译语句：用户输入仅作为绑定参数，不参与 SQL 结构拼接
    $stmt = $pdo->prepare('SELECT codec_path FROM cache_codec_registry WHERE cache_key = :key AND enabled = 1');
    $stmt->bindValue(':key', $cacheKey, PDO::PARAM_STR);
    $stmt->execute();
    $row = $stmt->fetch(PDO::FETCH_ASSOC);
    if ($row === false) {
        throw new RuntimeException('codec not registered');
    }
    $codecPath = (string)($row['codec_path'] ?? '');
    // realpath 归一化后强制限定在编解码器目录内，阻断目录穿越与符号链接逃逸
    $real = realpath($codecPath);
    $base = realpath(__DIR__ . '/codecs');
    if ($real === false || $base === false || !str_starts_with($real, $base . DIRECTORY_SEPARATOR)) {
        throw new RuntimeException('codec path escapes codec directory');
    }
    return $real;
}

$pdo = new PDO('sqlite:' . __DIR__ . '/cache_meta.db', null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$cacheKey = $_GET['key'] ?? '';
$codecFile = load_cache_codec($pdo, $cacheKey);
require $codecFile; // 表面危险：变量路径包含，CWE-98 形态
