package importer

import (
	"context"
	"database/sql"
	"encoding/gob"
	"io"
)

// Record 是导入批次的目标结构，字段全部为具体类型。
type Record struct {
	SKU   string
	Name  string
	Qty   int
	Price float64
}

// ImportGobBatch 解析上传的 gob 批次流并写入库存表。
func ImportGobBatch(ctx context.Context, db *sql.DB, src io.Reader) (int, error) {
	var batch []Record
	if err := gob.NewDecoder(src).Decode(&batch); err != nil {
		return 0, err
	}
	stmt, err := db.PrepareContext(ctx, "INSERT INTO inventory(sku, name, qty, price) VALUES (?, ?, ?, ?)")
	if err != nil {
		return 0, err
	}
	defer stmt.Close()
	imported := 0
	for _, rec := range batch {
		if _, err := stmt.ExecContext(ctx, rec.SKU, rec.Name, rec.Qty, rec.Price); err != nil {
			return imported, err
		}
		imported++
	}
	return imported, nil
}
