// QueryAuditLogs 审计日志查询：scope 选表，operator/action 过滤，limit 限条数。
func QueryAuditLogs(db *sql.DB, scope, operator, action, limitStr string) ([]byte, error) {
	table := map[string]string{"login": "login_audit", "admin": "admin_audit"}[scope]
	if table == "" {
		table = "audit_logs"
	}
	sqlText := fmt.Sprintf("SELECT id, operator, action, detail, created_at FROM %s WHERE 1=1", table)
	var args []interface{}
	if operator != "" {
		sqlText += " AND operator = ?"
		args = append(args, operator)
	}
	if action != "" {
		sqlText += " AND action = ?"
		args = append(args, action)
	}
	limit := 100
	if n, err := strconv.Atoi(limitStr); err == nil && n > 0 && n <= 1000 {
		limit = n
	}
	sqlText += " ORDER BY created_at DESC LIMIT ?"
	args = append(args, limit)
	rows, err := db.Query(sqlText, args...)
	if err != nil {
		return nil, fmt.Errorf("query audit logs: %w", err)
	}
	defer rows.Close()
	var out [][]string
	for rows.Next() {
		var id, op, act, detail, createdAt string
		_ = rows.Scan(&id, &op, &act, &detail, &createdAt)
		out = append(out, []string{id, op, act, detail, createdAt})
	}
	return json.Marshal(out)
}
