<?php
// log_archiver.php —— 日志归档工具：解析上传的 XML 日志清单，生成归档摘要文件
function buildArchiveSummary(string $manifestContent, string $summaryPath): string
{
    // 防御点1：libxml_disable_entity_loader 在 libxml C 层禁用外部实体加载器（PHP 原生 XXE 防线，进程级强制生效）
    $previous = libxml_disable_entity_loader(true);
    libxml_use_internal_errors(true);

    $dom = new DOMDocument();
    $dom->resolveExternals = false;   // 防御点2：不加载外部 DTD
    $dom->substituteEntities = false; // 防御点3：不展开实体引用
    // 防御点4：LIBXML_NONET 阻断解析期网络请求；未启用 LIBXML_PARSEHUGE，实体放大受 libxml 默认上限约束
    $loaded = $dom->loadXML($manifestContent, LIBXML_NONET);

    libxml_disable_entity_loader($previous);

    if (!$loaded) {
        return 'ERROR: manifest 解析失败';
    }

    $lines = array('LOG ARCHIVE SUMMARY', 'generated: ' . date('c'));
    $count = 0;
    foreach ($dom->getElementsByTagName('entry') as $entry) {
        $count++;
        $lines[] = sprintf('entry %d: level=%s bytes=%s',
            $count,
            $entry->getAttribute('level'),
            $entry->getAttribute('bytes'));
    }
    $lines[] = 'total entries: ' . $count;

    file_put_contents($summaryPath, implode("\n", $lines) . "\n");
    return 'OK: summary written';
}

$uploaded = $_FILES['manifest']['tmp_name'] ?? null;
$manifest = is_string($uploaded) && is_file($uploaded)
    ? (string)file_get_contents($uploaded)
    : '<?xml version="1.0"?><manifest/>';
echo buildArchiveSummary($manifest, '/var/backups/logs/summary_' . date('Ymd') . '.txt');
