        String resource = req.getParameter("resource");
        String user = (String) req.getSession().getAttribute("username");
        if (AclService.allowed(user, resource)) {
            return true;
        }
        Map<String, Object> model = new HashMap<>();
        model.put("resource", resource);
        model.put("user", user == null ? "anonymous" : user);
        // 模板源为 classpath 固定文件，用户输入仅作为数据模型变量，绝不作为模板语法解析
        Template tpl = fmCfg.getTemplate("denied_plain.ftl");
        StringWriter buf = new StringWriter();
        tpl.process(model, buf);
        resp.setContentType("text/html;charset=utf-8");
        // 防御点2：OWASP Java Encoder 在最终输出出口做 HTML 上下文编码
        resp.getWriter().write(Encode.forHtml(buf.toString()));
        AuditLog.write("deny " + user + " -> " + resource);
        return false;
    }
