public class AuditLogQueryService {

    enum AuditLogType {
        LOGIN("logs/audit/login.log"),
        EXPORT("logs/audit/export.log"),
        ADMIN("logs/audit/admin.log");

        final String relativePath;

        AuditLogType(String p) { this.relativePath = p; }
    }

    private static final Path BASE_DIR = Paths.get("/var/app/audit").normalize();

    private static final Map<AuditLogType, Path> ALLOWED = new EnumMap<>(AuditLogType.class);

    static {
        for (AuditLogType t : AuditLogType.values()) {
            ALLOWED.put(t, BASE_DIR.resolve(t.relativePath).normalize());
        }
    }

    public String readAuditLog(String requestedName) throws IOException {
        AuditLogType type;
        try {
            type = AuditLogType.valueOf(requestedName);
        } catch (IllegalArgumentException e) {
            throw new SecurityException("audit log not in whitelist: " + requestedName);
        }
        Path target = ALLOWED.get(type);
        if (!target.startsWith(BASE_DIR)) {
            throw new SecurityException("path escape detected");
        }
        return new String(Files.readAllBytes(target), StandardCharsets.UTF_8);
    }
}
