// ExportRows 按用户关键字过滤报表行并生成 HTML 导出片段。
func ExportRows(keyword string, rows []string) string {
	// 表面危险：keyword 疑似被原样拼入 ^(?:.*keyword)+$ 这类嵌套量词结构（CWE-1333 样式）
	encoded := regexp.QuoteMeta(keyword) // 防御一：正则上下文完整转义编码
	pattern := "^(?:.*" + encoded + ")+$"

	matcher, err := regexp.Compile(pattern)
	if err != nil {
		return "<p>filter rejected</p>"
	}

	var b strings.Builder
	for _, row := range rows {
		if matcher.MatchString(row) {
			b.WriteString("<tr><td>")
			b.WriteString(html.EscapeString(row)) // 防御二：输出处 HTML 上下文编码
			b.WriteString("</td></tr>")
		}
	}
	return fmt.Sprintf("<table>%s</table>", b.String())
}
