package cachecodec

import (
	"bytes"
	"errors"
	"html/template"
	"strings"
)

// CacheEntry 缓存条目；Value 可能携带外部注入的 HTML/JS 片段
type CacheEntry struct {
	Key   string
	Value string
}

// DecodeAndRender 解码缓存载荷并渲染为 HTML 片段
func DecodeAndRender(raw string) (string, error) {
	parts := strings.SplitN(raw, "|", 2)
	if len(parts) != 2 {
		return "", errors.New("cachecodec: malformed payload")
	}
	entry := &CacheEntry{Key: parts[0], Value: parts[1]}

	// html/template 的上下文感知自动转义由引擎强制开启，无关闭开关
	tmpl, err := template.New("cacheItem").Parse(
		`<div class="cache-item" data-key="{{.Key}}">{{.Value}}</div>`)
	if err != nil {
		return "", err
	}
	var out bytes.Buffer
	if err := tmpl.Execute(&out, entry); err != nil {
		return "", err
	}
	return out.String(), nil
}
