func handleInbound(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	p := payload{Title: r.FormValue("title"), Body: r.FormValue("body")}

	var buf bytes.Buffer
	if err := cardTpl.Execute(&buf, p); err != nil {
		http.Error(w, "render failed", http.StatusInternalServerError)
		return
	}

	const endpoint = "https://hooks.internal.example.net/notify"
	resp, err := http.Post(endpoint, "text/html; charset=utf-8", &buf)
	if err != nil {
		http.Error(w, "delivery failed", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	w.WriteHeader(http.StatusAccepted)
}

func main() {
	http.HandleFunc("/internal/event", handleInbound)
	http.ListenAndServe("127.0.0.1:8080", nil)
