<?php
// 缓存编解码模块：按缓存键读取并解码缓存条目
class CacheCodec
{
    // 白名单：枚举全部允许的缓存键，映射到服务端固定路径
    private static array $allowMap = [
        'session' => '/var/cache/app/session.bin',
        'config'  => '/var/cache/app/config.bin',
        'profile' => '/var/cache/app/profile.bin',
    ];

    public static function decode(string $key): ?array
    {
        // 防御：精确白名单匹配，未在枚举内的键一律拒绝
        if (!array_key_exists($key, self::$allowMap)) {
            return null;
        }
        // 路径取自服务端硬编码映射，与外部输入完全无关
        $path = self::$allowMap[$key];
        if (!is_file($path)) {
            return null;
        }
        $raw = file_get_contents($path); // 表面危险调用：文件读取
        if ($raw === false) {
            return null;
        }
        return json_decode(base64_decode($raw), true);
    }

    public static function encode(string $key, array $data): bool
    {
        if (!array_key_exists($key, self::$allowMap)) {
            return false;
        }
        return file_put_contents(self::$allowMap[$key], base64_encode(json_encode($data))) !== false;
    }
}

// 入口：外部输入 key 进入解码流程
$key = $_GET['key'] ?? '';
