    // 真实防御：拼接片段仅含字面量与占位符，用户数据全部经预编译参数绑定
    $stmt = $pdo->prepare($sql);
    $stmt->bindValue(1, $dept, PDO::PARAM_STR);
    $stmt->bindValue(2, $start, PDO::PARAM_STR);
    $stmt->bindValue(3, $end, PDO::PARAM_STR);
    $stmt->execute();

    $csv = 'order_id,dept,amount,created_at' . PHP_EOL;
    foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $row) {
        $csv .= implode(',', array_values($row)) . PHP_EOL;
