// 配置中心客户端：拉取 XML 配置并解析为键值数组
final class ConfigCenterClient
{
    private const ENDPOINT = 'http://config-center.internal.svc/v1/app-config.xml';

    public function loadConfig(): array
    {
        $ctx = stream_context_create(['http' => ['timeout' => 3]]);
        $raw = file_get_contents(self::ENDPOINT, false, $ctx);
        if ($raw === false) {
            throw new RuntimeException('配置中心不可达');
        }
        return $this->parse($raw);
    }

    private function parse(string $xml): array
    {
        if (PHP_VERSION_ID < 80000 || LIBXML_VERSION < 20900) {
            throw new RuntimeException('运行时过旧，拒绝解析配置 XML');
        }
        // 加固：外部实体加载器恒返回 null，任何外部 DTD/实体引用在解析层直接失败
        libxml_set_external_entity_loader(static function (?string $pub, ?string $sys, array $c): ?string {
            return null;
        });
        $doc = new DOMDocument();
        if ($doc->loadXML($xml, LIBXML_NONET | LIBXML_COMPACT) !== true) {
            throw new RuntimeException('配置 XML 非法');
        }
        if ($doc->doctype !== null) {
            throw new RuntimeException('配置文档不允许内嵌 DTD');
        }
        $config = [];
        foreach ($doc->getElementsByTagName('entry') as $n) {
            $config[$n->getAttribute('key')] = $n->textContent;
        }
        return $config;
    }
}
