package com.example.auth.middleware;

import java.util.List;
import java.util.concurrent.TimeUnit;

/**
 * 权限校验中间件：调用系统 id 命令核对请求者所属用户组，
 * 命中 REQUIRED_GROUP 才放行受保护资源。
 */
public class GroupCheckMiddleware {

    private static final String ID_BIN = "/usr/bin/id";
    private static final String REQUIRED_GROUP = "app-readonly";

    // userName 来自 HTTP 请求头 X-Auth-User，属不可信外部输入
    public boolean check(String userName) throws Exception {
        if (userName == null || userName.isEmpty() || userName.length() > 64) {
            return false;
        }
        // 关键防御：ProcessBuilder 采用参数列表形式，底层直接构造 argv 走 execve，
        // 全程不经过 /bin/sh；userName 中的 ; | && $() 反引号等元字符只会
        // 成为 id 的第 4 个独立参数中的普通字符，无法终止或派生新命令；
        // “--” 终止选项解析，防止以 - 开头的值被当作 id 的开关（防参数注入）。
        Process proc = new ProcessBuilder(
                List.of(ID_BIN, "-Gn", "--", userName))
                .start();
        if (!proc.waitFor(3, TimeUnit.SECONDS)) {
            proc.destroyForcibly();
            return false;
        }
        String groups = new String(proc.getInputStream().readAllBytes()).trim();
        for (String g : groups.split("\\s+")) {
            if (REQUIRED_GROUP.equals(g)) {
                return true;
            }
        }
        return false;
    }
}
