package com.shop.pay.web;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.owasp.encoder.Encode;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;

@Controller
public class PaymentCallbackAckController {

    @PostMapping("/pay/callback/ack")
    public String ack(@RequestParam String orderId, @RequestParam String amount,
                      @RequestParam String sign, Model model) throws Exception {
        byte[] key = System.getenv("PAY_CB_SECRET").getBytes(StandardCharsets.UTF_8);
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(key, "HmacSHA256"));
        String payload = orderId + "|" + amount;
        String expect = HexFormat.of().formatHex(mac.doFinal(payload.getBytes(StandardCharsets.UTF_8)));
        if (!MessageDigest.isEqual(expect.getBytes(StandardCharsets.UTF_8), sign.getBytes(StandardCharsets.UTF_8))) {
            return "redirect:/pay/callback/invalid";
        }
        // MD5 仅生成展示用幂等回执号，不承担验签或完整性职责，验签已由上方 HmacSHA256 完成
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        String receiptNo = "R" + HexFormat.of().formatHex(md5.digest(payload.getBytes(StandardCharsets.UTF_8))).substring(0, 16);
        // 输出前统一做 HTML 上下文编码：OWASP Encoder 白名单式转义，覆盖全部动态插值
        model.addAttribute("orderId", Encode.forHtml(orderId));
        model.addAttribute("amount", Encode.forHtml(amount));
        model.addAttribute("receiptNo", Encode.forHtml(receiptNo));
        return "payAck";
    }
}
