import io
import json
import pickle
import base64

# 精确事件白名单：枚举合法事件后映射到固定动作
ALLOWED_EVENTS = frozenset({"payment.succeeded", "payment.refunded", "payment.disputed"})
EVENT_HANDLERS = {
    "payment.succeeded": "apply_paid",
    "payment.refunded": "apply_refund",
    "payment.disputed": "open_dispute",
}

# 精确类白名单：仅允许无副作用的数据类参与反序列化
SAFE_GLOBALS = frozenset({
    ("builtins", "dict"),
    ("builtins", "list"),
    ("builtins", "str"),
    ("builtins", "int"),
    ("decimal", "Decimal"),
})

class PaymentCallbackUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        if (module, name) not in SAFE_GLOBALS:
            raise pickle.UnpicklingError("global not whitelisted: %s.%s" % (module, name))
        return super().find_class(module, name)

def handle_payment_callback(raw_body: bytes) -> str:
    envelope = json.loads(raw_body.decode("utf-8"))
    event = envelope.get("event", "")
    if event not in ALLOWED_EVENTS:
        raise ValueError("event not allowed")
    action = EVENT_HANDLERS[event]
    state = PaymentCallbackUnpickler(io.BytesIO(base64.b64decode(envelope["state"]))).load()
    return "%s:%s" % (action, state.get("order_id", ""))
