package main

import (
	"time"

	"go.uber.org/zap"
)

// 定时对账任务：周期性比对渠道流水与本地订单
type Reconciler struct {
	logger *zap.SugaredLogger
}

func NewReconciler() *Reconciler {
	cfg := zap.NewProductionConfig() // 生产配置：JSON 编码器，自动转义控制字符
	cfg.Encoding = "json"            // 显式确认编码器未被替换为 console 或 plain
	logger, _ := cfg.Build()
	return &Reconciler{logger: logger.Sugar()}
}

// Run 每隔 interval 拉取渠道流水并记录对账差异
func (r *Reconciler) Run(interval time.Duration, fetch func() (string, error)) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for range ticker.C {
		channelFlow, err := fetch() // 渠道侧返回内容不可信，可能携带换行伪造日志
		if err != nil {
			r.logger.Errorw("对账流水拉取失败", "err", err)
			continue
		}
		// 不可信数据直接进入日志格式串，表面为 CWE-117 日志注入
		r.logger.Infof("对账差异: 渠道流水=%s", channelFlow)
	}
}

func main() {
	r := NewReconciler()
	r.Run(time.Minute, func() (string, error) {
		return "CH20240601|金额100.00|状态成功", nil // 模拟渠道流水返回
	})
}
