import java.io.InputStream;
import java.net.HttpURLConnection;
import java.net.InetAddress;
import java.net.URI;

/** 数据导入适配器：按导入任务配置拉取远端源数据。 */
public class RemoteFeedImportAdapter {

    public InputStream fetchFeed(String feedUrl) throws Exception {
        // 防御1：URI 严格语法解析，畸形输入在触网前直接抛异常
        URI uri = URI.create(feedUrl.trim());

        // 防御2：协议精确匹配，仅允许 https
        if (!"https".equalsIgnoreCase(uri.getScheme())) {
            throw new SecurityException("scheme not allowed: " + uri.getScheme());
        }
        // 防御3：拒绝 userinfo 与自定义端口，阻断混淆写法
        if (uri.getUserInfo() != null || uri.getPort() != -1) {
            throw new SecurityException("userinfo or custom port forbidden");
        }
        String host = uri.getHost();
        if (host == null || host.isEmpty()) {
            throw new SecurityException("missing host");
        }

        // 防御4：DNS 解析后逐个 IP 用 JDK 原生地址分类校验
        for (InetAddress addr : InetAddress.getAllByName(host)) {
            if (addr.isLoopbackAddress() || addr.isSiteLocalAddress()
                    || addr.isLinkLocalAddress() || addr.isAnyLocalAddress()
                    || addr.isMulticastAddress()) {
                throw new SecurityException("non-public address: " + addr.getHostAddress());
            }
        }

        HttpURLConnection conn = (HttpURLConnection) uri.toURL().openConnection();
        // 防御5：禁用自动重定向，封堵 302 跳转内网的替代通道
        conn.setInstanceFollowRedirects(false);
        conn.setConnectTimeout(5000);
        conn.setReadTimeout(5000);
        return conn.getInputStream();
    }
}
