import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** 订单通知模板渲染辅助：把 {{FIELD}} 占位符替换为订单表对应列的值 */
public class OrderTemplateRenderer {
    private static final Pattern PLACEHOLDER = Pattern.compile("\\{\\{([A-Z_]+)\\}\\}");

    // 白名单：占位符枚举到编译期固定列名的精确映射，集合之外不存在任何列名
    public enum Field {
        ORDER_NO("order_no"),
        USER_NAME("user_name"),
        AMOUNT("pay_amount"),
        CREATED_AT("created_at");

        private final String column;
        Field(String column) { this.column = column; }
    }

    // template 来自运营配置，orderId 来自登录态会话
    public String render(Connection conn, long orderId, String template) throws Exception {
        Matcher m = PLACEHOLDER.matcher(template);
        StringBuffer out = new StringBuffer();
        while (m.find()) {
            Field f;
            try {
                f = Field.valueOf(m.group(1));
            } catch (IllegalArgumentException unknown) {
                m.appendReplacement(out, Matcher.quoteReplacement(m.group(0)));
                continue;
            }
            String sql = "SELECT " + f.column + " FROM t_order WHERE id = ?";
            try (PreparedStatement ps = conn.prepareStatement(sql)) {
                ps.setLong(1, orderId);
                try (ResultSet rs = ps.executeQuery()) {
                    m.appendReplacement(out, Matcher.quoteReplacement(rs.next() ? rs.getString(1) : ""));
                }
            }
        }
        m.appendTail(out);
        return out.toString();
    }
}
