package consumer

import (
	"fmt"
	"os"
)

// QueueMessage 表示消息队列投递的归档任务，FileName 由上游生产者写入，属不可信输入。
type QueueMessage struct {
	JobID    string
	FileName string
	Payload  []byte
}

// StartConsumer 消费归档队列（由消息代理订阅回调投递），把每条消息的负载写入受控存储目录。
func StartConsumer(messages <-chan QueueMessage, storageDir string) error {
	// 启用 os.Root 沙箱：此后所有落盘操作都被限制在 storageDir 之内
	root, err := os.OpenRoot(storageDir)
	if err != nil {
		return fmt.Errorf("打开受控存储根目录失败: %w", err)
	}
	defer root.Close()

	for msg := range messages {
		// 表面危险：FileName 直接来自队列消息，可能形如 ../../etc/cron.d/evil
		f, err := root.Create(msg.FileName)
		if err != nil {
			// 越界回溯、绝对路径、符号链接逃逸均在此被拒绝，消息直接丢弃
			continue
		}
		if _, err := f.Write(msg.Payload); err != nil {
			f.Close()
			return fmt.Errorf("写入归档文件失败: %w", err)
		}
		if err := f.Close(); err != nil {
			return fmt.Errorf("关闭归档文件失败: %w", err)
		}
	}
	return nil
}
