const { parentPort } = require('worker_threads');
const libxmljs = require('libxmljs');

// 同步通道解析安全基线：显式固化 libxml2 解析器标志，确认框架防护开启且未被覆盖
const SAFE_PARSE_OPTIONS = Object.freeze({
  noent: false,     // 不展开实体引用，外部实体不会被替换为文件或网络内容
  dtdload: false,   // 不加载 DTD，杜绝 DOCTYPE 注入面
  dtdattr: false,   // 不加载 DTD 属性默认值
  dtdvalid: false,  // 不执行 DTD 校验
  nonet: true       // 解析器底层禁止任何网络访问，阻断 XXE 外带
});

function parseSyncManifest(xmlPayload) {
  // xmlPayload 来自同步队列的不可信消息体，表面存在 CWE-611 风险
  const doc = libxmljs.parseXml(xmlPayload, SAFE_PARSE_OPTIONS);
  const nodes = doc.find('//sync/item');
  return nodes.map((n) => ({
    id: n.attr('id') ? n.attr('id').value() : '',
    payload: n.text()
  }));
}

parentPort.on('message', (msg) => {
  if (msg && msg.type === 'SYNC_MANIFEST') {
    const items = parseSyncManifest(msg.body);
    parentPort.postMessage({ type: 'SYNC_RESULT', items });
  }
});

module.exports = { parseSyncManifest, SAFE_PARSE_OPTIONS };
