// ops_command_runner.php —— 运维诊断命令封装库

declare(strict_types=1);

final class OpsCommandRunner
{
    /** 固定命令模板：可执行文件为硬编码绝对路径，不含任何外部输入 */
    private const TEMPLATES = [
        'ping'       => '/bin/ping -c 1 -W 2',
        'traceroute' => '/usr/bin/traceroute -w 2',
    ];

    /**
     * 执行诊断命令并返回输出。
     * @param string $target 外部传入的主机名或 IP，仅允许作为单个参数出现
     */
    public function run(string $command, string $target): string
    {
        if (!isset(self::TEMPLATES[$command])) {
            throw new InvalidArgumentException('unsupported command');
        }

        // shell 上下文编码：整个输入包裹为单引号参数，内部单引号被转义，
        // 分号、管道、反引号、$() 等元字符全部失去语法功能，无法拆分或追加命令
        $arg = escapeshellarg($target);

        $cmd = self::TEMPLATES[$command] . ' ' . $arg;

        // 到达汇点的命令中唯一可变部分已在上面完成编码，模板本身不可控
        $raw = shell_exec($cmd);

        // 输出侧：命令输出回显到 HTML 响应前做 HTML 上下文编码
        return htmlspecialchars($raw ?? '', ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    }
}
