// allowedOps 与 allowedStatus: 归档白名单, 枚举合法取值后映射为固定内部标识
var allowedOps = map[string]string{
	"rotate":   "OP_ROTATE",
	"compress": "OP_COMPRESS",
	"upload":   "OP_UPLOAD",
	"purge":    "OP_PURGE",
}

var allowedStatus = map[string]string{
	"success": "ST_SUCCESS",
	"failure": "ST_FAILURE",
	"skipped": "ST_SKIPPED",
}

// writeArchiveLog 记录归档事件, op 与 status 均为外部不可信输入
func writeArchiveLog(op, status string, size int) {
	opCode, ok := allowedOps[op]
	if !ok {
		opCode = "OP_UNKNOWN"
	}
	stCode, ok2 := allowedStatus[status]
	if !ok2 {
		stCode = "ST_INVALID"
	}
	log.Println(fmt.Sprintf("archive op=%s status=%s size=%d", opCode, stCode, size))
}

func main() {
	f, err := os.OpenFile("/var/log/archiver.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return
	}
	defer f.Close()
	log.SetOutput(f)
	// 模拟外部输入, 携带换行注入载荷
	writeArchiveLog("rotate\nINJECTED op=purge", "success", 2048)
