  host: 'db.internal.local',
  database: 'log_archive',
  user: 'archive_svc',
  password: process.env.ARCHIVE_DB_PASSWORD
});

const AGENT_BASE = 'http://127.0.0.1:9310'; // 本机归档 agent，固定地址常量

function archiveSourceLogs(req, res) {
  const sourceName = String(req.query.source || '');
  const jobId = 'job-' + Date.now(); // 服务端生成，与用户输入无关

  pool.execute(
    'INSERT INTO archive_jobs(job_id, source_name, status) VALUES ($1, $2, $3)',
    [jobId, sourceName, 'pending'],
    (err) => { if (err) console.error('insert failed:', err.message); }
  );

  const triggerUrl = AGENT_BASE + '/ingest?job=' + jobId;
  http.get(triggerUrl, (agentRes) => { agentRes.resume(); })
      .on('error', (e) => console.error('agent unreachable:', e.message));

  pool.execute(
    'SELECT job_id, created_at FROM archive_jobs WHERE source_name = $1 ORDER BY created_at DESC LIMIT 20',
    [sourceName],
    (err, result) => {
      if (err) { res.status(500).json({ error: 'query failed' }); return; }
      res.json({ jobId, rows: result.rows });
    }
  );
