    // 未启用 LIBXML_NOENT/LIBXML_DTDLOAD,外部实体与远程 DTD 不会被解析
    if (!$doc->loadXML($rawXml, LIBXML_NONET | LIBXML_COMPACT)) {
        return '<p class="err">回执解析失败,已转人工复核</p>';
    }
    $pick = static function (string $tag) use ($doc): string {
        $node = $doc->getElementsByTagName($tag)->item(0);
        return $node instanceof DOMNode ? $node->nodeValue : '';
    };
    $orderId  = $pick('orderId');
    $supplier = $pick('supplierName');
    $amount   = $pick('amount');
    // 输出期防御:所有 XML 派生值进入 HTML 前统一做上下文编码
    $esc = static fn (string $v): string =>
