import html
import json
from pathlib import Path
from PIL import Image


def extract_metadata(image_path):
    """提取上传图片的文件名与 EXIF UserComment(攻击者完全可控)。"""
    with Image.open(image_path) as img:
        raw_comment = img.getexif().get(0x9286, b"")
    if isinstance(raw_comment, bytes):
        raw_comment = raw_comment.decode("utf-8", "replace")
    return {"name": Path(image_path).name, "comment": raw_comment}


def render_gallery_page(records):
    """图片处理流水线: 用元数据拼装相册 HTML 报告页。"""
    figures = []
    for rec in records:
        safe_name = html.escape(rec["name"], quote=True)
        safe_comment = html.escape(rec["comment"], quote=True)
        figures.append(
            '<figure><img src="/static/{0}" alt="{1}">'
            "<figcaption>{1}</figcaption></figure>".format(safe_name, safe_comment)
        )
    return "<html><body>\n" + "\n".join(figures) + "\n</body></html>"


def build_json_manifest(records):
    """替代通道: 同一批元数据另生成 JSON 清单, 以 application/json 响应返回。"""
    items = [{"name": r["name"], "comment": r["comment"]} for r in records]
    return json.dumps(items, ensure_ascii=True)


def pipeline(uploaded_paths):
    records = [extract_metadata(p) for p in uploaded_paths]
    return {"html_page": render_gallery_page(records), "manifest": build_json_manifest(records)}
