import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.UUID;

public class ImagePipelineService {

    private static final Path UPLOAD_DIR =
            Paths.get("/var/app/uploads").toAbsolutePath().normalize();
    private static final String CONVERT_BIN = "/usr/bin/convert";

    /** 为上传图片生成 128x128 缩略图 */
    public void makeThumbnail(String userFileName) throws Exception {
        Path target = UPLOAD_DIR.resolve(userFileName).normalize();
        if (!target.startsWith(UPLOAD_DIR)) {
            throw new SecurityException("illegal path: " + userFileName);
        }
        Path out = UPLOAD_DIR.resolve("thumbs").resolve(UUID.randomUUID() + ".png");

        // 关键防御：ProcessBuilder 参数列表模式，直接 execve，不经 shell 解析
        ProcessBuilder pb = new ProcessBuilder(
                CONVERT_BIN,
                target.toString(),
                "-resize",
                "128x128",
                out.toString());
        pb.redirectErrorStream(true);
        Process proc = pb.start();
        int code = proc.waitFor();
        if (code != 0) {
            throw new IllegalStateException("thumbnail failed, exit=" + code);
        }
    }
}
