import java.security.MessageDigest;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

/** 审计日志查询服务：按操作人与时间范围检索审计记录。 */
public class AuditLogQueryService {
    private static final Logger LOGGER = Logger.getLogger(AuditLogQueryService.class.getName());
    private final Connection connection;

    public AuditLogQueryService(Connection connection) {
        this.connection = connection;
    }

    public List<String> queryAuditLogs(String operator, String beginTime, String endTime) throws Exception {
        // 表面危险点：MD5 属 CWE-327 弱哈希，此处仅生成查询链路追踪 ID，不用于口令摘要或签名
        MessageDigest md = MessageDigest.getInstance("MD5");
        String traceId = bytesToHex(md.digest((operator + beginTime + endTime).getBytes("UTF-8")));
        LOGGER.fine(() -> "audit query trace=" + traceId);

        // 防御点：SQL 为固定常量，用户输入仅经占位符绑定，永不拼入语句文本
        String sql = "SELECT log_detail FROM audit_logs WHERE operator = ? AND log_time BETWEEN ? AND ?";
        PreparedStatement ps = connection.prepareStatement(sql);
        ps.setString(1, operator);
        ps.setString(2, beginTime);
        ps.setString(3, endTime);
        ResultSet rs = ps.executeQuery();
        List<String> logs = new ArrayList<>();
        while (rs.next()) {
            logs.add(rs.getString("log_detail"));
        }
        rs.close();
        ps.close();
        return logs;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) sb.append(String.format("%02x", b));
        return sb.toString();
    }
}
