package main

import (
	"archive/tar"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

var logRoot = "/var/log/app" // 归档固定根目录（绝对路径）

// archiveHandler 读取用户指定的日志文件并写入 tar 归档流
func archiveHandler(w http.ResponseWriter, r *http.Request) {
	userPath := r.URL.Query().Get("name") // 外部输入，可能携带 ../ 穿越序列
	// 出口规范化：Join 内部执行 Clean，消解 .. 与绝对路径注入
	joined := filepath.Clean(filepath.Join(logRoot, userPath))
	rel, relErr := filepath.Rel(logRoot, joined)
	// 出口校验：相对路径回退到根之外即整体拒绝
	if relErr != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(os.PathSeparator)) {
		http.Error(w, "path escapes log root", http.StatusBadRequest)
		return
	}
	f, err := os.Open(joined) // 打开的路径已被证明位于根内
	if err != nil {
		http.Error(w, "log not found", http.StatusNotFound)
		return
	}
	defer f.Close()
	// 输出编码：tar 条目名采用 ToSlash 规范化的根内相对路径
	hdr := &tar.Header{Name: filepath.ToSlash(rel), Mode: 0o600}
	w.Header().Set("Content-Type", "application/x-tar")
	tw := tar.NewWriter(w)
	defer tw.Close()
	_ = tw.WriteHeader(hdr)
	_, _ = io.Copy(tw, f)
}

func main() {
	http.HandleFunc("/archive", archiveHandler)
	_ = http.ListenAndServe("127.0.0.1:8080", nil)
}
