	endpoint string
	logger   *log.Logger
}

func NewConfigClient(endpoint string, logger *log.Logger) *ConfigClient {
	return &ConfigClient{endpoint: endpoint, logger: logger}
}

// PullConfig 拉取配置项；远端返回值可能含任意字节（含换行回车）
func (c *ConfigClient) PullConfig(key string) (string, error) {
	resp, err := http.Get(c.endpoint + "/v1/config?key=" + key)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	buf := make([]byte, 4096)
	n, _ := resp.Body.Read(buf)
	rawValue := strings.TrimSpace(string(buf[:n]))
	// 表面危险：远端未校验数据进入日志；实际由 %q 在输出点做全量转义
	c.logger.Printf("config refreshed key=%q value=%q", key, rawValue)
	return rawValue, nil
}

func main() {
	logger := log.New(os.Stdout, "[cfg] ", log.LstdFlags)
	client := NewConfigClient("http://config.internal:8080", logger)
	if v, err := client.PullConfig("feature.flag"); err == nil {
		fmt.Println("loaded bytes:", len(v))
	}
}
