// handleExport 报表导出服务：将用户指定报表转换为 PDF
func handleExport(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("report") // 不可信来源：HTTP 查询参数
	if name == "" {
		http.Error(w, "missing report", http.StatusBadRequest)
		return
	}
	// filepath.Base 安全解析：剥离目录成分，仅保留文件名
	safeName := filepath.Base(name)
	if safeName == "." || safeName == ".." {
		http.Error(w, "bad report name", http.StatusBadRequest)
		return
	}

	ctx, cancel := context.WithTimeout(r.Context(), 30*time.Second)
	defer cancel()

	// 参数化执行：argv 数组直传 execve，全程不经 /bin/sh 解析
	cmd := exec.CommandContext(ctx, exportBin, "--input", safeName, "--outdir", "/var/export")
	if err := cmd.Run(); err != nil {
		log.Printf("export failed: %v", err)
		http.Error(w, "export failed", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusOK)
}

func main() {
	http.HandleFunc("/export", handleExport)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
