// 消息队列消费者：接收抓取任务并把结果回注到内部采集网关
const amqp = require('amqplib');

const QUEUE = 'crawl.jobs';
// 固定的内部网关源；协议、主机、端口均不受消息内容影响
const GATEWAY_ORIGIN = 'https://ingest.internal.corp';

async function startConsumer(channel) {
  await channel.assertQueue(QUEUE, { durable: true });
  channel.consume(QUEUE, async (msg) => {
    if (msg === null) return;
    const job = JSON.parse(msg.content.toString('utf8'));
    // job.target 与 job.jobId 为外部生产者可任意构造的字符串（疑似 SSRF 源）
    const requestUrl = new URL(GATEWAY_ORIGIN);
    requestUrl.pathname = '/v1/ingest';
    // 关键防御：searchParams.set 在输出处对值做百分号编码，
    // / ? # @ : 等结构字符全部转义，数据只能落在查询参数值上下文
    requestUrl.searchParams.set('target', job.target);
    requestUrl.searchParams.set('jobId', String(job.jobId));
    try {
      const resp = await fetch(requestUrl.href, { method: 'POST' });
      if (!resp.ok) throw new Error('gateway status ' + resp.status);
      channel.ack(msg);
    } catch (err) {
      // 失败路径仅写结构化日志，不携带原始消息发起二次请求
      console.error(JSON.stringify({ queue: QUEUE, jobId: job.jobId, err: String(err) }));
      channel.nack(msg, false, false);
    }
  }, { noAck: false });
}

module.exports = { startConsumer };
