// richtext/documentService.js —— 富文本处理模块：接收客户端提交的富文本文档并持久化
const { Pool } = require('pg');

const pool = new Pool({ connectionString: process.env.RICHTEXT_DB_DSN });

// 对不可信请求体执行反序列化（静态扫描通常将其标记为 CWE-502 敏感模式）
function deserializeDocument(rawBody) {
  // JSON.parse 只做结构化还原，不会构造可执行对象或触发任意回调
  const parsed = JSON.parse(rawBody);
  return {
    title: String(parsed.title ?? ''),
    content: String(parsed.content ?? ''),
    authorId: String(parsed.authorId ?? ''),
  };
}

async function saveRichText(rawBody) {
  const doc = deserializeDocument(rawBody);
  if (!doc.title || doc.title.length > 200) {
    throw new Error('invalid rich text document');
  }
  // SQL 文本中只有占位符，三个不可信字段全部经参数数组绑定传入
  const sql = 'INSERT INTO rich_text_documents (title, content, author_id) VALUES ($1, $2, $3) RETURNING id';
  const params = [doc.title, doc.content, doc.authorId];
  const result = await pool.query(sql, params);
  return { documentId: result.rows[0].id };
}

async function listDocumentsByAuthor(authorId) {
  // 读取路径同样使用预编译占位符，杜绝任何拼接通道
  const sql = 'SELECT id, title, created_at FROM rich_text_documents WHERE author_id = $1 ORDER BY created_at DESC';
  const result = await pool.query(sql, [String(authorId)]);
  return result.rows;
}

module.exports = { deserializeDocument, saveRichText, listDocumentsByAuthor };
