  ['staging', 'http://config-center.staging.internal:8080/v1/config'],
  ['dev', 'http://config-center.dev.internal:8080/v1/config']
]);

function fetchConfig(env, configKey) {
  // 防御：精确白名单查找，env 仅作键，URL 取自映射值
  if (!CONFIG_SERVERS.has(env)) {
    throw new Error('env not allowed');
  }
  const baseUrl = CONFIG_SERVERS.get(env);
  const target = baseUrl + '?key=' + encodeURIComponent(configKey);
  return new Promise((resolve, reject) => {
    http.get(target, res => {
      let data = '';
      res.on('data', chunk => { data += chunk; });
      res.on('end', () => resolve(JSON.parse(data)));
    }).on('error', reject);
  });
}

// 入口：query 来自外部请求参数
function handleConfigQuery(query) {
  return fetchConfig(query.env, query.key);
}

module.exports = { handleConfigQuery };
