import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import org.owasp.encoder.Encode;

/** 缓存编解码模块：解码远端节点心跳缓存条目并渲染集群状态页片段 */
public class CachePeerCodec {

    /** 探活端点为编译期常量，仅指向本机健康检查服务 */
    private static final String HEALTH_ENDPOINT = "http://127.0.0.1:8081/cache/health";

    /** encodedEntry 为请求侧提交的 Base64 心跳缓存条目，内容形如远端节点状态地址 */
    public String decodeAndRender(String encodedEntry) throws Exception {
        byte[] raw = Base64.getDecoder().decode(encodedEntry);
        String peer = new String(raw, StandardCharsets.UTF_8);

        // 解析远端节点地址，仅用于状态页展示，不向该地址发起任何连接
        URL peerUrl = new URL(peer);
        String display = peerUrl.toExternalForm();

        // 探活请求固定打向本机健康检查端点，与 peer 无数据交集
        HttpURLConnection conn = (HttpURLConnection) new URL(HEALTH_ENDPOINT).openConnection();
        conn.setConnectTimeout(2000);
        conn.setReadTimeout(2000);
        conn.getResponseCode();
        conn.disconnect();

        // 输出前按 HTML 上下文做实体编码，防止缓存条目内容破坏页面结构
        return "<li data-peer=\"" + Encode.forHtmlAttribute(display)
                + "\">节点 " + Encode.forHtml(peer) + " 心跳正常</li>";
    }
}
