const path = require('path');
const fs = require('fs');
const express = require('express');

const AUDIT_ROOT = path.resolve(__dirname, 'audit-logs');
const app = express();

// 权限校验中间件：仅允许读取审计目录内的日志文件
function auditPermissionMiddleware(req, res, next) {
  const requested = req.query.file;
  if (typeof requested !== 'string' || requested.length === 0) {
    return res.status(400).json({ error: 'missing file parameter' });
  }

  // 防御一：path.resolve 规范化后做目录归属校验
  const resolved = path.resolve(AUDIT_ROOT, requested);
  const rel = path.relative(AUDIT_ROOT, resolved);
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) {
    return res.status(403).json({ error: 'forbidden path' });
  }

  // 防御二：realpath 解析符号链接后复核归属，阻断软链逃逸
  fs.promises.realpath(resolved).then((canonical) => {
    const rel2 = path.relative(AUDIT_ROOT, canonical);
    if (rel2 === '' || rel2.startsWith('..') || path.isAbsolute(rel2)) {
      return res.status(403).json({ error: 'forbidden path' });
    }
    res.locals.auditFile = canonical;
    return next();
  }).catch(() => res.status(404).json({ error: 'log not found' }));
}

app.get('/audit/view', auditPermissionMiddleware, (req, res) => {
  res.sendFile(res.locals.auditFile);
});

app.listen(8080);
