    public Map<String, Object> findResourceMeta(String fileName, String versionTag) throws SQLException {
        StringBuilder sql = new StringBuilder(
                "SELECT resource_path, mime_type, size_bytes FROM static_resources WHERE status = 'ACTIVE'");
        List<Object> params = new ArrayList<>();
        if (fileName != null && !fileName.isEmpty()) {
            sql.append(" AND resource_name = ?");
            params.add(fileName);
        }
        if (versionTag != null && !versionTag.isEmpty()) {
            sql.append(" AND version_tag = ?");
            params.add(versionTag);
        }
        try (Connection conn = dataSource.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql.toString())) {
            for (int i = 0; i < params.size(); i++) {
                ps.setObject(i + 1, params.get(i));
            }
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    Map<String, Object> meta = new HashMap<>();
                    meta.put("path", rs.getString("resource_path"));
                    meta.put("mime", rs.getString("mime_type"));
                    meta.put("size", rs.getLong("size_bytes"));
                    return meta;
                }
            }
        }
        return Collections.emptyMap();
    }
}
