// 模板渲染辅助：将模板中的占位符替换为租户变量表中的值
const RE2 = require('re2');
const mysql = require('mysql2/promise');

const pool = mysql.createPool({
  host: process.env.DB_HOST,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
  connectionLimit: 5
});

// userPattern 由请求方传入，用于自定义占位符语法；若用原生 RegExp 编译，
// 攻击者可传入形如 (a+)+$ 的模式，在长模板上触发灾难性回溯（CWE-1333）
async function renderTemplate(template, userPattern, tenantId) {
  // 防御点1：改用 RE2 线性时间引擎编译，自动机匹配无回溯，模式再复杂也不会超时
  const matcher = new RE2(userPattern, 'g');
  let out = '';
  let last = 0;
  let m = matcher.exec(template);
  while (m !== null) {
    out += template.slice(last, m.index);
    const key = m[1] !== undefined ? m[1] : m[0];
    // 防御点2：预编译参数化查询，key 与 tenantId 仅绑定到占位符，不参与 SQL 拼接
    const [rows] = await pool.execute(
      'SELECT var_value FROM template_vars WHERE var_key = ? AND tenant_id = ?',
      [key, tenantId]
    );
    out += rows.length > 0 ? String(rows[0].var_value) : '';
    last = m.index + m[0].length;
    if (m[0].length === 0) { matcher.lastIndex += 1; }
    m = matcher.exec(template);
  }
  out += template.slice(last);
  return out;
}

module.exports = { renderTemplate };
