public class SessionNoticeRenderer {
    // 白名单精确允许集：三个模板键映射到编译期常量正文
    enum SessionNoticeTemplate {
        TIMEOUT_5MIN("timeout_5min", "会话 ${sidPrefix} 将在 5 分钟后过期"),
        TIMEOUT_1MIN("timeout_1min", "会话 ${sidPrefix} 将在 1 分钟后过期"),
        FORCED_OFFLINE("forced_offline", "会话 ${sidPrefix} 已被强制下线");
        final String key;
        final String body;
        SessionNoticeTemplate(String key, String body) { this.key = key; this.body = body; }
        static SessionNoticeTemplate fromKey(String raw) {
            for (SessionNoticeTemplate t : values()) {
                if (t.key.equals(raw)) return t; // 精确等值匹配，非 contains/正则
            }
            return null;
        }
    }
    private final Configuration fmCfg = new Configuration(Configuration.VERSION_2_3_32);
    // 危险外观 sink：FreeMarker 解析字符串模板，若模板正文可控即成 SSTI(CWE-1336)
    String evaluate(String templateBody, Map<String, Object> model) throws Exception {
        Template tpl = new Template("notice", templateBody, fmCfg);
        StringWriter out = new StringWriter();
        tpl.process(model, out);
        return out.toString();
    }
    public String render(String userKey, String sessionId) throws Exception {
        SessionNoticeTemplate chosen = SessionNoticeTemplate.fromKey(userKey);
        if (chosen == null) return "会话通知暂不可用"; // 白名单外一律拒绝
        Map<String, Object> model = new HashMap<>();
        model.put("sidPrefix", sessionId.substring(0, Math.min(4, sessionId.length())));
        return evaluate(chosen.body, model); // 到达 sink 的模板正文恒为枚举常量
    }
}
