// auditBase 为部署配置写死的内网审计服务地址（不含查询串与凭据）
const auditBase = "http://audit-svc.internal/logs"

// handleAuditQuery 按操作者账号查询审计日志并转发结果
func handleAuditQuery(w http.ResponseWriter, r *http.Request) {
	actor := r.URL.Query().Get("actor")
	if actor == "" {
		http.Error(w, "missing actor", http.StatusBadRequest)
		return
	}
	// actor 为外部输入，直接拼接出站 URL 看似可造成 SSRF（CWE-918）
	// 但出口处使用 url.QueryEscape 做百分号编码：问号、与号、井号、
	// 斜杠、百分号以及回车换行等结构字符全部被编码为普通数据字符，
	// 请求主机与路径完全由常量 auditBase 决定，无法改变请求目标
	endpoint := auditBase + "?actor=" + url.QueryEscape(actor)
	resp, err := http.Get(endpoint)
	if err != nil {
		http.Error(w, "audit service unavailable", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	w.Header().Set("Content-Type", "application/json")
	io.Copy(w, resp.Body)
}

func main() {
	http.HandleFunc("/audit/query", handleAuditQuery)
	http.ListenAndServe("127.0.0.1:8080", nil)
}
