const fs = require('fs');
const path = require('path');

const TEMPLATE_ROOT = path.join(__dirname, 'templates');

// 白名单：枚举全部允许的模板名，并逐一映射到服务端固定路径
const TEMPLATE_WHITELIST = {
  'article': path.join(TEMPLATE_ROOT, 'article.html'),
  'notice': path.join(TEMPLATE_ROOT, 'notice.html'),
  'product': path.join(TEMPLATE_ROOT, 'product.html'),
  'plain': path.join(TEMPLATE_ROOT, 'plain.html')
};

function escapeHtml(text) {
  return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function loadRichTextTemplate(userTemplate) {
  if (typeof userTemplate !== 'string') {
    throw new Error('模板名必须为字符串');
  }
  // 精确匹配白名单键：含 ../、绝对路径或未知名称的输入均无法命中
  const resolved = Object.prototype.hasOwnProperty.call(TEMPLATE_WHITELIST, userTemplate)
    ? TEMPLATE_WHITELIST[userTemplate]
    : null;
  if (resolved === null) {
    throw new Error('模板不在允许列表中');
  }
  // 读取路径完全来自映射表常量，用户输入仅作键查找，不参与任何路径拼接
  return fs.readFileSync(resolved, 'utf8');
}

function renderRichText(templateName, content) {
  const tpl = loadRichTextTemplate(templateName);
  return tpl.replace('<!--BODY-->', escapeHtml(content));
}

module.exports = { renderRichText };
