        }
        String trustedPath = rs.getString("template_path");
        rs.close();
        ps.close();
        File templateFile = new File(trustedPath);
        if (!templateFile.exists()) {
            throw new IllegalStateException("template file missing");
        }
        return Files.readAllBytes(templateFile.toPath());
    }
