function onCallbackMessage(PDO $pdo, string $body): void
{
    $msg = json_decode($body, true);
    if (!is_array($msg) || !isset($msg['event'], $msg['callback_url'], $msg['task_id'])) {
        error_log('drop malformed envelope');
        return;
    }

    $callbackUrl = (string) $msg['callback_url'];
    $parts = parse_url($callbackUrl);
    if ($parts === false || empty($parts['host'])) {
        error_log('drop unparsable callback url');
        return;
    }

    // 处理前探测本地健康检查端点（固定地址，与消息内容无关）
    $probeUrl = 'http://127.0.0.1:8081/health';
    $ch = curl_init($probeUrl);
    curl_setopt($ch, CURLOPT_TIMEOUT, 3);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_exec($ch);
    curl_close($ch);

    $stmt = $pdo->prepare(
        'INSERT INTO callback_registry (event, callback_url, url_host, task_id)
         VALUES (:event, :url, :host, :task)'
    );
    $stmt->bindValue(':event', (string) $msg['event'], PDO::PARAM_STR);
    $stmt->bindValue(':url', $callbackUrl, PDO::PARAM_STR);
    $stmt->bindValue(':host', (string) $parts['host'], PDO::PARAM_STR);
