<?php
// 数据同步工作线程：从同步队列读取任务批次并写入数据库
function sync_worker_process(string $queueMessage, PDO $db): int
{
    if ($queueMessage === '') {
        return 0;
    }

    // 队列消息为序列化数据；禁用一切类实例化，仅允许数组/标量结构
    $payload = unserialize($queueMessage, ['allowed_classes' => false]);
    if (!is_array($payload) || !isset($payload['batch_id'], $payload['records'])
        || !is_array($payload['records'])) {
        return 0;
    }

    $stmt = $db->prepare(
        'INSERT INTO sync_records (batch_id, row_key, row_value) VALUES (:b, :k, :v)'
    );

    $applied = 0;
    foreach ($payload['records'] as $row) {
        if (!is_array($row) || !isset($row['key'], $row['value'])) {
            continue;
        }
        $stmt->execute([
            ':b' => (string) $payload['batch_id'],
            ':k' => (string) $row['key'],
            ':v' => (string) $row['value'],
        ]);
        $applied++;
    }

    return $applied;
}
