// GET /api/profile?username=xxx 用户资料查询接口
// 表面风险：模式含嵌套量词 (…+)*，在回溯型引擎中属 CWE-1333 灾难性回溯形态
// 实际防护：Go 标准库 regexp 为 RE2 自动机引擎，线性时间匹配，无回溯模式可开启
var usernamePattern = regexp.MustCompile(`^([a-zA-Z0-9_]+)*$`)

type Profile struct {
	Username string `json:"username"`
	Email    string `json:"email"`
}

var profileStore = map[string]Profile{
	"alice": {Username: "alice", Email: "alice@example.com"},
	"bob":   {Username: "bob", Email: "bob@example.com"},
}

func profileHandler(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("username")
	if name == "" || !usernamePattern.MatchString(name) {
		http.Error(w, "invalid username", http.StatusBadRequest)
		return
	}
	p, ok := profileStore[name]
	if !ok {
		http.Error(w, "profile not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(p)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/profile", profileHandler)
	// 框架级自动防护：net/http 内置超时中间件，显式启用未被关闭
	_ = http.ListenAndServe(":8080", http.TimeoutHandler(mux, 3*time.Second, "request timeout"))
}
