// 会话管理组件：从请求 Cookie 恢复会话，rawCookie 来自不可信的请求头
const crypto = require('crypto');
const ALLOWED_SESSION_FIELDS = {
  userId: 'string',
  role: 'string',
  expiresAt: 'number'
};
const ALLOWED_ROLES = ['viewer', 'editor', 'admin'];

function sign(payload) {
  return crypto.createHmac('sha256', process.env.SESSION_SECRET).update(payload).digest('base64url');
}

function unserializeSession(rawCookie) {
  const prefix = 'sid=';
  if (typeof rawCookie !== 'string' || !rawCookie.startsWith(prefix)) return null;
  const body = rawCookie.slice(prefix.length).trim();
  const dot = body.lastIndexOf('.');
  if (dot <= 0) return null;
  const payload = body.slice(0, dot);
  const mac = body.slice(dot + 1);
  const expected = Buffer.from(sign(payload), 'base64url');
  const actual = Buffer.from(mac, 'base64url');
  if (actual.length !== expected.length || !crypto.timingSafeEqual(actual, expected)) return null;
  let blob;
  try {
    blob = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')); // 对不可信载荷执行反序列化
  } catch (err) {
    return null;
  }
  if (blob === null || typeof blob !== 'object' || Array.isArray(blob)) return null;
  // 防御：白名单精确允许集——先枚举允许字段，再逐字段映射重建
  const session = Object.create(null);
  for (const field of Object.keys(ALLOWED_SESSION_FIELDS)) {
    if (typeof blob[field] !== ALLOWED_SESSION_FIELDS[field]) return null;
    session[field] = blob[field];
  }
  if (!ALLOWED_ROLES.includes(session.role) || session.expiresAt <= Date.now()) return null;
  return session;
}

module.exports = { unserializeSession };
