const { XMLParser } = require('fast-xml-parser');

const app = express();

// 支付网关异步回调：网关以 XML 报文通知支付结果
app.post('/payment/notify', express.text({ type: ['application/xml', 'text/xml'] }), (req, res) => {
  const rawXml = req.body; // 不可信来源：外部网关回调报文
  const sign = String(req.header('X-Pay-Sign') || '');
  const expect = crypto.createHmac('sha256', process.env.PAY_CALLBACK_SECRET || '')
    .update(rawXml).digest('hex');
  if (sign.length !== expect.length ||
      !crypto.timingSafeEqual(Buffer.from(sign), Buffer.from(expect))) {
    return res.status(401).type('application/json')
      .send(JSON.stringify({ return_code: 'FAIL' }));
  }

  // 解析回调 XML：processEntities 设为 false 后实体处理整体关闭，内外部实体一律不展开
  const parser = new XMLParser({ processEntities: false, ignoreDeclaration: true });
  let notify;
  try {
    const doc = parser.parse(rawXml);
    notify = (doc && typeof doc === 'object' && doc.notify) || {};
  } catch (e) {
    return res.status(400).type('application/json')
      .send(JSON.stringify({ return_code: 'FAIL', reason: 'BAD_XML' }));
  }

  const outTradeNo = String(notify.out_trade_no == null ? '' : notify.out_trade_no);
  const totalFee = String(notify.total_fee == null ? '' : notify.total_fee);

  // 用户查单跳转地址：查询参数逐段做 URL 组件编码
  const resultUrl = '/pay/result?order=' + encodeURIComponent(outTradeNo)
    + '&fee=' + encodeURIComponent(totalFee);

  // 应答网关：响应体整体交给 JSON.stringify 完成 JSON 上下文转义，不做手工拼接
  res.type('application/json')
    .send(JSON.stringify({ return_code: 'SUCCESS', result_url: resultUrl }));
});

app.listen(9090);
