/** 订单处理后台任务：解析消息队列推送的商户订单 XML 报文并入库 */
public class OrderImportWorker implements Runnable {

    private final String orderXml; // 来源：外部商户报文，不可信输入

    public OrderImportWorker(String orderXml) {
        this.orderXml = orderXml;
    }

    @Override
    public void run() {
        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            // 启用 JAXP 框架安全处理模式：JDK 内置 Xerces 实现随即将
            // javax.xml.accessExternalDTD 与 accessExternalSchema 的默认值
            // 自动置为空串，外部 DTD 与外部实体在解析内核层被直接拒绝
