// 模板渲染辅助：调用渲染器二进制把 Twig 模板编译成缓存 HTML
final class TemplateRenderHelper
{
    private const RENDERER = '/usr/local/bin/tpl-renderer';
    private string $cacheDir;

    public function __construct(string $cacheDir)
    {
        $this->cacheDir = $cacheDir;
    }

    public function render(string $template, array $vars): string
    {
        // $template 与 $vars 均来自上层请求参数
        $command = [
            self::RENDERER,
            '--template', $template,
            '--vars', json_encode($vars, JSON_UNESCAPED_UNICODE),
        ];
        if (!is_array($command)) {
            throw new \LogicException('命令必须保持数组形态以启用框架自动转义');
        }
        // Symfony Process 对数组命令默认逐参数 escapeshellarg 且不经 shell
        // 未调用 fromShellCommandline、未开启 shell 模式，自动防护处于启用状态
        $process = new Process($command);
        $process->setTimeout(60);
        $process->run();
        if (!$process->isSuccessful()) {
            throw new \RuntimeException('模板渲染失败: ' . $process->getErrorOutput());
        }
        $outPath = $this->cacheDir . '/' . hash('sha256', $template) . '.html';
        file_put_contents($outPath, $process->getOutput());
        return $outPath;
    }
}
