package indexer

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"time"
)

func BuildIndex(srcURL string) (string, error) {
	u, err := url.Parse(srcURL)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") {
		return "", fmt.Errorf("bad source url: %s", srcURL)
	}
	tr := &http.Transport{DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
		host, port, err := net.SplitHostPort(addr)
		if err != nil {
			return nil, err
		}
		ip := net.ParseIP(host)
		if ip == nil {
			addrs, rerr := net.DefaultResolver.LookupIPAddr(ctx, host)
			if rerr != nil || len(addrs) == 0 {
				return nil, fmt.Errorf("resolve failed: %s", host)
			}
			ip = addrs[0].IP
		}
		if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsUnspecified() {
			return nil, fmt.Errorf("blocked internal address: %s", ip)
		}
		d := net.Dialer{Timeout: 3 * time.Second}
		return d.DialContext(ctx, network, net.JoinHostPort(ip.String(), port))
	}}
	client := &http.Client{Transport: tr, Timeout: 5 * time.Second}
	resp, err := client.Get(u.String())
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	buf := make([]byte, 4096)
	n, _ := resp.Body.Read(buf)
	return string(buf[:n]), nil
}
