const crypto = require('crypto');
const { execFile } = require('child_process');
const express = require('express');
const app = express();
app.use(express.json());

const RECONCILE_BIN = '/usr/local/bin/reconcile-payment';
const CALLBACK_SECRET = process.env.PAYMENT_CALLBACK_SECRET;

// 支付回调：第三方网关异步通知入口
app.post('/payment/callback', (req, res) => {
  const { orderId, amount, currency, signature } = req.body;

  // 第一步：HMAC-SHA256 验签，常数时间比较防伪造回调
  const payload = orderId + '|' + amount + '|' + currency;
  const expected = crypto.createHmac('sha256', CALLBACK_SECRET).update(payload).digest('hex');
  const sigBuf = Buffer.from(String(signature || ''), 'utf8');
  const expBuf = Buffer.from(expected, 'utf8');
  if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
    return res.status(401).json({ error: 'invalid signature' });
  }

  // 第二步：金额安全解析，强制数值化并拒绝非有限值
  const amountNum = Number(amount);
  if (!Number.isFinite(amountNum) || amountNum <= 0) {
    return res.status(400).json({ error: 'invalid amount' });
  }

  // 第三步：参数化执行，execFile 以 argv 数组传参且 shell:false，
  // 全程不启动 /bin/sh，分号、反引号、$() 等元字符只作为普通参数字符串
  execFile(RECONCILE_BIN,
    ['--order', String(orderId), '--amount', amountNum.toFixed(2), '--currency', String(currency)],
    { shell: false, timeout: 5000 },
    (err, stdout) => {
      if (err) return res.status(500).json({ error: 'reconcile failed' });
      res.json({ ok: true, output: String(stdout).slice(0, 200) });
    });
});

app.listen(8080);
