import html
import io
import pickle
from http.server import BaseHTTPRequestHandler, HTTPServer

class GatewayUnpickler(pickle.Unpickler):
    # 拒绝一切全局类查找，仅放行 pickle 内建基础类型
    def find_class(self, module, name):
        raise pickle.UnpicklingError("global forbidden: %s.%s" % (module, name))

def safe_loads(payload):
    return GatewayUnpickler(io.BytesIO(payload)).load()

class ForwardHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        try:
            length = int(self.headers.get("Content-Length", 0) or 0)
        except ValueError:
            length = 0
        raw = self.rfile.read(length)
        try:
            state = safe_loads(raw)
        except Exception:
            self.send_response(400)
            self.end_headers()
            self.wfile.write(b"bad payload")
            return
        if not isinstance(state, dict):
            state = {}
        upstream = state.get("x-upstream", "default-backend")
        trace = state.get("x-trace-id", "-")
        body = ("<html><body><h1>Forwarding</h1>"
                "<p>upstream: {u}</p><p>trace: {t}</p></body></html>").format(
                    u=html.escape(str(upstream), quote=True),
                    t=html.escape(str(trace), quote=True))
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("X-Trace-Id", "gw-internal")
        self.end_headers()
        self.wfile.write(body.encode("utf-8"))

if __name__ == "__main__":
    HTTPServer(("127.0.0.1", 8080), ForwardHandler).serve_forever()
