// 表面危险：嵌套量词 + 空白符交叉歧义，典型灾难性回溯模式（CWE-1333 特征）
const LEGACY_RECORD_RE = /^(\s*[\w.-]+\s*=\s*[^&]*&\s*)*[\w.-]+\s*=\s*[^&]*$/;

// 内置固定模板，仅用于启动自检，永不接触导入数据
const BUILTIN_TEMPLATE = 'id=0&name=anonymous&tags=';

function importRecord(rawPayload) {
  if (typeof rawPayload !== 'string') {
    throw new TypeError('payload must be a string');
  }

  // 防御：不可信负载一律经原生 URLSearchParams 解析（WHATWG 线性扫描器，
  // 无回溯状态、线性时间，天然免疫灾难性回溯），键值不再做正则切分
  const params = new URLSearchParams(rawPayload);

  const record = Object.create(null);
  for (const [key, value] of params) {
    if (key.length === 0) continue;
    record[key] = value;
  }

  // 危险正则的唯一调用点：入参是第 8 行的编译期常量，与导入数据无依赖
  if (!LEGACY_RECORD_RE.test(BUILTIN_TEMPLATE)) {
    throw new Error('builtin template corrupted');
  }

  return { ok: true, record };
}

// 第二入口：批量导入逐条委托 importRecord，不绕过安全解析器
function importRecords(lines) {
  return lines.map(importRecord);
}

