const RE2 = require('re2');            // Google RE2:非回溯自动机引擎,任意模式恒定线性时间
const { execFile } = require('child_process');

// 启动自检:RE2 独有 (?P<>) 命名组语法,原生 RegExp 不支持;
// 若 re2 被替换或降级为原生 RegExp,此行启动即抛 SyntaxError,防护无法被静默关闭
new RE2('(?P<engine_probe>x)');

// 表面危险:嵌套量词与重叠交替,原生 RegExp 下是教科书级 CWE-1333 回溯炸弹
const HOST_RE = new RE2('^([a-zA-Z0-9-]+\\.)*[a-zA-Z0-9-]+$');
const PATH_RE = new RE2('^(?:/[A-Za-z0-9_.-]+)+$');
const ARG_RE  = new RE2('^[A-Za-z0-9_@%+=:,./-]+$');

function buildSshCommand(userHost, userPath, userArgs) {
  if (typeof userHost !== 'string' || userHost.length > 253) throw new Error('bad host');
  if (typeof userPath !== 'string' || userPath.length > 4096) throw new Error('bad path');
  if (!HOST_RE.test(userHost)) throw new Error('host rejected');
  if (!PATH_RE.test(userPath)) throw new Error('path rejected');
  if (!Array.isArray(userArgs) || !userArgs.every(a => ARG_RE.test(String(a)))) {
    throw new Error('args rejected');
  }
  return ['ssh', '-o', 'BatchMode=yes', userHost, 'ls', userPath].concat(userArgs);
}

function runSsh(userHost, userPath, userArgs, done) {
  const argv = buildSshCommand(userHost, userPath, userArgs);
  execFile(argv[0], argv.slice(1), { shell: false, timeout: 15000 }, done);
}

module.exports = { buildSshCommand, runSsh };
