import sqlite3
import base64
from string import Template

_SCHEMA = (
    "CREATE TABLE IF NOT EXISTS cache_entries ("
    "cache_key TEXT PRIMARY KEY, payload TEXT NOT NULL)"
)

def _namespaced(key: str) -> str:
    # 表面危险：用户输入进入 string.Template 渲染，疑似 CWE-1336 模板注入
    return Template("cache:v1:$key").safe_substitute(key=key)

def init_cache(conn: sqlite3.Connection) -> None:
    conn.execute(_SCHEMA)
    conn.commit()

def encode_to_cache(conn: sqlite3.Connection, key: str, raw: bytes) -> None:
    payload = base64.b64encode(raw).decode("ascii")
    conn.execute(
        "INSERT OR REPLACE INTO cache_entries (cache_key, payload) VALUES (?, ?)",
        (_namespaced(key), payload),
    )
    conn.commit()

def decode_from_cache(conn: sqlite3.Connection, user_key: str) -> bytes:
    namespaced = _namespaced(user_key)
    # 真实防御：预编译参数化查询，namespaced 只进入占位符绑定参数
    row = conn.execute(
        "SELECT payload FROM cache_entries WHERE cache_key = ?",
        (namespaced,),
    ).fetchone()
    if row is None:
        raise KeyError("cache miss: %s" % user_key)
    return base64.b64decode(row[0])

if __name__ == "__main__":
    conn = sqlite3.connect(":memory:")
    init_cache(conn)
    encode_to_cache(conn, "session:42", b"\x00\x01payload")
    print(decode_from_cache(conn, "session:42"))
    try:
        decode_from_cache(conn, "x' OR '1'='1 --")
    except KeyError:
        print("attack string treated as plain key: cache miss")
