import tarfile
import defusedxml.ElementTree as SafeET

ARCHIVE = "/var/log/incoming/logs_archive.tar.gz"
MANIFEST = "manifest.xml"


def extract_manifest(archive_path: str) -> bytes:
    """从日志归档包中读取 manifest.xml 清单文件内容。"""
    with tarfile.open(archive_path, "r:gz") as tar:
        member = tar.extractfile(MANIFEST)
        if member is None:
            raise FileNotFoundError("manifest.xml 不存在于归档中")
        return member.read()


def parse_manifest(xml_bytes: bytes):
    """解析清单 XML，返回待归档日志条目列表。"""
    # defusedxml 安全解析器：forbid_dtd 禁止 DTD 声明，
    # forbid_entities 禁止任何实体定义，XXE 载荷在此直接抛异常
    root = SafeET.fromstring(xml_bytes, forbid_dtd=True, forbid_entities=True)
    entries = []
    for node in root.findall("entry"):
        entries.append({
            "path": node.get("path", ""),
            "level": node.findtext("level", default="info"),
        })
    return entries


if __name__ == "__main__":
    raw = extract_manifest(ARCHIVE)
    for item in parse_manifest(raw):
        print(item)
