package com.ops.alert.mq;

import java.io.ByteArrayInputStream;
import java.io.ObjectInputFilter;
import java.io.ObjectInputStream;
import java.util.Base64;
import org.owasp.encoder.Encode;

/** 消息队列消费者：消费告警事件并回显到运维看板 HTML 片段。 */
public class AlertEventConsumer {

    private final StringBuilder dashboardHtml;

    public AlertEventConsumer(StringBuilder dashboardHtml) {
        this.dashboardHtml = dashboardHtml;
    }

    // 队列回调入口：消息体为 Base64 编码的 Java 序列化 AlertEvent
    public void onMessage(String base64Body) throws Exception {
        byte[] raw = Base64.getDecoder().decode(base64Body);
        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(raw));
        // JEP 290 白名单：仅放行 DTO 与 String，其余类在解析阶段即被拒绝
        ois.setObjectInputFilter(ObjectInputFilter.Config.createFilter(
                "com.ops.alert.mq.AlertEvent;java.base/java.lang.String;!*"));
        AlertEvent event = (AlertEvent) ois.readObject();
        ois.close();

        // 输出处上下文编码：字段仅作为纯文本进入看板 HTML
        dashboardHtml.append("<div class='alert'>")
                .append("<span class='src'>").append(Encode.forHtml(event.getSource())).append("</span>")
                .append("<pre class='note'>").append(Encode.forHtml(event.getNote())).append("</pre>")
                .append("</div>");
    }

    public static class AlertEvent implements java.io.Serializable {
        private static final long serialVersionUID = 1L;
        private String source;
        private String note;
        public String getSource() { return source; }
        public String getNote() { return note; }
    }
}
