// 缓存编解码模块：从 localStorage 读取 base64 编码的 HTML 快照并回放到预览面板
const KEY_PREFIX = 'snap:';

function decodeSnapshot(key) {
  const raw = localStorage.getItem(KEY_PREFIX + key);
  if (typeof raw !== 'string') return null;
  try {
    return atob(raw); // 解码出任意 HTML，可能携带 <script> 或 <img onerror=...>
  } catch (err) {
    return null;
  }
}

export function replaySnapshot(key, host) {
  const html = decodeSnapshot(key);
  if (html === null) return false;
  const frame = document.createElement('iframe');
  // 原生沙箱：未授予 allow-scripts 与 allow-same-origin，快照内脚本无法执行
  frame.setAttribute('sandbox', '');
  frame.setAttribute('referrerpolicy', 'no-referrer');
  frame.srcdoc = html; // 看似将不可信 HTML 直接写入 DOM
  frame.style.width = '100%';
  frame.style.height = '240px';
  host.replaceChildren(frame);
  return true;
}
