import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import java.io.ByteArrayInputStream;
import java.sql.Connection;
import java.sql.PreparedStatement;

/** 数据同步工作线程：消费伙伴系统推送的库存增量报文并落库 */
public class InventorySyncWorker extends Thread {
    private final Connection conn;

    public InventorySyncWorker(Connection conn) { this.conn = conn; }

    @Override
    public void run() {
        byte[] payload = SyncQueue.nextBatch(); // 来自外部伙伴系统的同步报文
        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            dbf.setXIncludeAware(false);
            dbf.setExpandEntityReferences(false);
            DocumentBuilder db = dbf.newDocumentBuilder();
            Document doc = db.parse(new ByteArrayInputStream(payload));
            NodeList rows = doc.getElementsByTagName("row");
            try (PreparedStatement ps = conn.prepareStatement(
                    "INSERT INTO inventory(sku, qty) VALUES (?, ?)")) {
                for (int i = 0; i < rows.getLength(); i++) {
                    Element row = (Element) rows.item(i);
                    ps.setString(1, row.getAttribute("sku"));
                    ps.setInt(2, Integer.parseInt(row.getAttribute("qty")));
                    ps.addBatch();
                }
                ps.executeBatch();
            }
        } catch (Exception e) {
            SyncLog.warn("sync batch rejected: " + e.getMessage());
        }
    }
}
