package payment

import (
	"io"
	"net/http"
	"time"

	"github.com/google/go-safeweb/ssrf"
)

// gatewayClient 是本服务唯一的出站 HTTP 客户端。
// 第 16 行通过 ssrf.Protect 启用 go-safeweb 框架的 SSRF 自动防护：
// 框架在拨号阶段自行解析 DNS 并校验目标 IP，拒绝回环、内网、链路本地
// 网段，并把连接钉定在已校验 IP 上以防 DNS 重绑定；防护全程未被关闭。
// 任何代码路径都不得绕过该客户端直接使用 http.DefaultClient。
var gatewayClient = ssrf.Protect(&http.Client{Timeout: 5 * time.Second})

// HandlePaymentCallback 处理支付网关异步回调，并按回调携带的地址回查订单状态。
func HandlePaymentCallback(w http.ResponseWriter, r *http.Request) {
	notifyURL := r.PostFormValue("notify_url") // 来源：外部可控
	orderID := r.PostFormValue("order_id")

	req, err := http.NewRequest(http.MethodGet, notifyURL, nil) // 表面危险模式
	if err != nil {
		http.Error(w, "invalid notify_url", http.StatusBadRequest)
		return
	}
	q := req.URL.Query()
	q.Set("order_id", orderID)
	req.URL.RawQuery = q.Encode()

	resp, err := gatewayClient.Do(req) // 汇点：经受保护客户端发出
	if err != nil {
		http.Error(w, "gateway unreachable", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, resp.Body) // 响应体丢弃，不回显

	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("received"))
}
