package main
import (
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
)

const (
	scanBin    = "/usr/bin/clamscan" // 固定二进制绝对路径,编译期常量
	uploadRoot = "/var/lib/uploadmgr/incoming"
)

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, 32<<20)
	file, header, err := r.FormFile("attachment")
	if err != nil {
		http.Error(w, "missing attachment", http.StatusBadRequest)
		return
	}
	defer file.Close()
	name := filepath.Base(header.Filename) // 剥离目录分量,仅保留文件名
	target := filepath.Join(uploadRoot, name)
	dst, err := os.OpenFile(target, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		http.Error(w, "cannot store file", http.StatusBadRequest)
		return
	}
	defer dst.Close()
	if _, err := io.Copy(dst, file); err != nil {
		http.Error(w, "write failed", http.StatusInternalServerError)
		return
	}
	// 防线:exec.Command 以 argv 数组直接 execve 不经 shell,; | && $() 等元字符只作普通参数
	if err := exec.Command(scanBin, "--no-summary", target).Run(); err != nil {
		http.Error(w, "scan failed", http.StatusUnprocessableEntity)
		return
	}
	w.Write([]byte("stored and clean: " + name))
}
func main() {
	http.HandleFunc("/upload", uploadHandler)
	http.ListenAndServe("127.0.0.1:8080", nil)
}
